-- =====================================================================================
-- JaeTravel: import of budget-tours-data.ts (14 budget tours)
-- Target: the Payload v2 schema (PostgreSQL) from jaetravel-v2.zip
--
-- HOW TO RUN (on an empty database that already has the Payload tables, i.e. after `pnpm payload migrate`):
--     psql "$DATABASE_URL" -f jaetravel-budget-import.sql
-- It is safe to run again: anything that already exists (same slug or image URL) is skipped, never overwritten.
-- It runs inside one transaction: if anything fails, nothing is saved.
-- =====================================================================================
BEGIN;

-- 1. Prerequisites: seasons and tour templates (only created when missing) ----------------------------
DO $do$
DECLARE s int; tid int; v text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM seasons) THEN
  END IF;
  FOREACH v IN ARRAY ARRAY['standard','budget','accessible','migration'] LOOP
    IF NOT EXISTS (SELECT 1 FROM templates WHERE variant = v::enum_templates_variant) THEN
        SELECT k.ord, tid, md5(tid::text || v || 'sec' || k.key), k.key::enum_templates_sections_key, true
        FROM unnest(CASE v
          WHEN 'budget' THEN ARRAY['facts','highlights','whyCheaper','tabs','bestTime','faq','similar']
          WHEN 'accessible' THEN ARRAY['facts','highlights','accessibility','tabs','bestTime','faq','similar']
          ELSE ARRAY['facts','highlights','offerBanner','tabs','bestTime','faq','similar'] END) WITH ORDINALITY AS k(key, ord);
        SELECT k.ord, tid, md5(tid::text || v || 'tab' || k.key), k.key::enum_templates_tabs_key, true
        FROM unnest(ARRAY['itinerary','inclusions','exclusions','booking','gallery','videos']) WITH ORDINALITY AS k(key, ord);
    END IF;
  END LOOP;
END $do$;

-- 2. Images -------------------------------------------------------------------------------------------
-- Images keep the address they had on the old site (for example /masai-mara-migration.jpg), so copy the
-- files from the old project's public folder into this project's public folder (see the README note).
-- Five images are hosted on ik.imagekit.io and are used from there as they are.

WITH src(url, filename, mime, alt) AS (VALUES
  ($j$/pexels-bharath-kumar-venkatesh-1417371218-30125343-scaled.jpg$j$, $j$pexels-bharath-kumar-venkatesh-1417371218-30125343-scaled.jpg$j$, $j$image/jpeg$j$, $j$Masai Mara 3 Days Budget Land Cruiser Safari Kenya 2026$j$),
  ($j$/pexels-gil-daix-2046153486-29339542-scaled.jpg$j$, $j$pexels-gil-daix-2046153486-29339542-scaled.jpg$j$, $j$image/jpeg$j$, $j$Masai Mara 3 Days Superior Budget Shared Land Cruiser Safari Kenya 2026$j$),
  ($j$/sutirta-budiman-E8JdyPcSA8o-unsplash-5-scaled.jpg$j$, $j$sutirta-budiman-E8JdyPcSA8o-unsplash-5-scaled.jpg$j$, $j$image/jpeg$j$, $j$Samburu 3 Days Private Safari Kenya 2026$j$),
  ($j$/1000025509-1.jpg$j$, $j$1000025509-1.jpg$j$, $j$image/jpeg$j$, $j$Masai Mara$j$),
  ($j$/436772123_840707984764076_1007538712348891897_n.jpg$j$, $j$436772123_840707984764076_1007538712348891897_n.jpg$j$, $j$image/jpeg$j$, $j$Masai Mara$j$),
  ($j$/grace-nandi-KzxdgYVkSdY-unsplash-1-scaled.jpg$j$, $j$grace-nandi-KzxdgYVkSdY-unsplash-1-scaled.jpg$j$, $j$image/jpeg$j$, $j$Masai Mara$j$),
  ($j$/hongbin-qSSQ98ziK2Y-unsplash-scaled.jpg$j$, $j$hongbin-qSSQ98ziK2Y-unsplash-scaled.jpg$j$, $j$image/jpeg$j$, $j$Masai Mara-Nakuru-Amboseli 6 Days Shared Safari Kenya 2026$j$),
  ($j$/harshil-gudka-aKcVSSDotgo-unsplash-8-scaled.jpg$j$, $j$harshil-gudka-aKcVSSDotgo-unsplash-8-scaled.jpg$j$, $j$image/jpeg$j$, $j$Best of Kenya 7 Days Budget Shared Safari 2026$j$),
  ($j$/david-clode-zsalJqyCY8M-unsplash-1-scaled.jpg$j$, $j$david-clode-zsalJqyCY8M-unsplash-1-scaled.jpg$j$, $j$image/jpeg$j$, $j$Kenya Big 5 7 Days Budget Safari 2026$j$),
  ($j$/eileen-flynn-bu4BF_ZUmXI-unsplash-2-scaled.jpg$j$, $j$eileen-flynn-bu4BF_ZUmXI-unsplash-2-scaled.jpg$j$, $j$image/jpeg$j$, $j$Kenya 8 Days Budget Big 5 Safari 2026$j$),
  ($j$/pexels-gil-daix-2046153486-29435757-1-scaled.jpg$j$, $j$pexels-gil-daix-2046153486-29435757-1-scaled.jpg$j$, $j$image/jpeg$j$, $j$Kenya's Best 10 Days Budget Safari 2026$j$),
  ($j$/masai-mara-safari.jpg$j$, $j$masai-mara-safari.jpg$j$, $j$image/jpeg$j$, $j$3-Day Masai Mara Budget Safari 2026$j$),
  ($j$/amboseli_elephants_at_sun_set-2__1200w.jpg$j$, $j$amboseli_elephants_at_sun_set-2__1200w.jpg$j$, $j$image/jpeg$j$, $j$6-Day Masai Mara, Nakuru & Amboseli Budget Safari 2026$j$),
  ($j$/ostrich_family_in_amboseli-2__1200w.jpg$j$, $j$ostrich_family_in_amboseli-2__1200w.jpg$j$, $j$image/jpeg$j$, $j$5-Day Masai Mara, Naivasha & Amboseli Budget Safari 2026$j$),
  ($j$/kenya-safari-landscape.jpg$j$, $j$kenya-safari-landscape.jpg$j$, $j$image/jpeg$j$, $j$Kenya safari landscape$j$)
),
new_rows AS (
  SELECT url, url, filename, mime FROM src
  WHERE NOT EXISTS (SELECT 1 FROM media m WHERE m.url = src.url)
  RETURNING id, url
)
SELECT src.alt, 'en', new_rows.id FROM new_rows JOIN src ON src.url = new_rows.url;


-- 3. Destination (Kenya, only created when missing) --------------------------
DO $do$ DECLARE v int; BEGIN
  IF NOT EXISTS (SELECT 1 FROM destinations WHERE slug = $j$kenya$j$) THEN

Kenya is the birthplace of the safari and remains one of Africa's premier wildlife destinations. From the Masai Mara Great Migration to Mount Kenya and the coastal beaches, Kenya offers unmatched diversity.$j$, 'en', v);
  END IF;
END $do$;

-- (no vehicles in this file) -------------------------------------------------------------------------------------------

-- 5. Tours ---------------------------------------------------------------------------------------------
-- Prices: your files hold one price per tour, so every season and group size starts at that price per person.
-- Refine them in the admin (Tours > Pricing) when you have prices by season and group size.
-- budget-tours-data.ts: masai-mara-3-days-budget-land-cruiser-safari
DO $do$ DECLARE v int; BEGIN
  IF NOT EXISTS (SELECT 1 FROM tours WHERE slug = $j$masai-mara-3-days-budget-land-cruiser-safari$j$) THEN
    VALUES ($j$masai-mara-3-days-budget-land-cruiser-safari$j$, false, true, false, false,
      (SELECT id FROM templates WHERE variant = $j$budget$j$::enum_templates_variant ORDER BY id LIMIT 1),
      (SELECT id FROM destinations WHERE slug = $j$kenya$j$),
      3, (SELECT id FROM media WHERE url = $j$/pexels-bharath-kumar-venkatesh-1417371218-30125343-scaled.jpg$j$ ORDER BY id LIMIT 1),
      NULL, 4, 12) RETURNING id INTO v;
    VALUES ($j$Masai Mara 3 Days Budget Land Cruiser Safari Kenya 2026$j$, $j$Perfect short Masai Mara budget safari. See the Big Five on shared game drives, stay in budget camps, enjoy all meals. Great for first-timers and solo travelers. From $450.$j$, $j${"root": {"type": "root", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "paragraph", "children": [{"type": "text", "text": "Experience the magic of Africa's most famous wildlife reserve on our affordable 3-Day Masai Mara Budget Safari Kenya 2026. This carefully crafted itinerary offers first-time safari-goers and budget-conscious travelers an authentic African wildlife experience without compromising on quality or wildlife viewing opportunities. Starting from just $450 per person, this cheap Masai Mara safari package represents exceptional value for money, providing all the essentials for an unforgettable adventure in one of the world's premier wildlife destinations.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Masai Mara National Reserve needs little introduction - it's Kenya's flagship wildlife area, renowned for its high density of predators, spectacular Great Migration (July-October), and classic African savannah landscapes. Our 3-day budget safari captures the essence of this iconic reserve in a compact timeframe, perfect for travelers with limited time or those wanting to add a wildlife experience to a broader Kenya itinerary.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Your journey begins in Nairobi, where you'll join fellow travelers in a specially equipped 4x4 Land Cruiser for the scenic drive to Masai Mara. As you traverse the Great Rift Valley, you'll witness Kenya's dramatic landscapes unfolding before you. Upon arrival at the reserve, you'll check into our carefully selected budget tented camp - comfortable safari accommodation that maintains authentic atmosphere while keeping costs reasonable. These camps feature shared twin tents with ensuite facilities, dining areas, and evening campfires where you can share stories with fellow adventurers.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "The safari experience revolves around game drives - the heart of any African wildlife adventure. Our schedule includes approximately 8-10 hours of game viewing across multiple drives, timed for optimal wildlife activity. Early morning drives catch predators at their most active, while afternoon sessions offer golden light photography opportunities. Your experienced guide will share extensive knowledge about animal behaviors, tracking techniques, and conservation efforts throughout your journey.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Wildlife viewing in Masai Mara is exceptional year-round. While the Great Migration (approximately 1.5 million wildebeest and zebra crossing from Tanzania's Serengeti) occurs July-October, the Mara's resident wildlife provides spectacular viewing anytime. You'll search for the Big Five (lion, leopard, elephant, buffalo, and rhino), along with cheetahs, hyenas, giraffes, zebras, and numerous antelope species. The reserve's varied habitats - from open grasslands to riverine forests - support diverse ecosystems that your guide will help you understand and appreciate.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This budget safari Kenya 2026 package includes all essentials: shared 4x4 Land Cruiser transport, park fees, accommodation, meals, and professional guiding. We've eliminated unnecessary luxuries to keep costs accessible while maintaining core wildlife experiences. The shared group model (4-12 travelers) significantly reduces individual costs while creating social travel experiences perfect for solo travelers, couples, or small groups.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Beyond wildlife, you'll have opportunities for cultural interactions with Maasai communities (optional, additional cost), learning about their traditional pastoralist lifestyle and conservation role. These cultural exchanges add depth to your safari experience, providing context about human-wildlife coexistence in modern Kenya.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Practical considerations are well addressed. Our budget camps provide comfortable beds, mosquito nets, and basic amenities. Meals are hearty and varied, accommodating dietary requirements with advance notice. Transportation in pop-up roof vehicles ensures optimal viewing and photography opportunities. Your guide handles all logistics, allowing you to focus entirely on the wildlife experience.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This affordable Kenya safari 2026 represents smart travel planning. While longer safaris obviously offer more comprehensive experiences, this 3-day package delivers meaningful wildlife encounters within practical constraints. It's perfect for testing whether safari travel suits you, adding wildlife experiences to business or beach holidays, or simply experiencing Africa's premier wildlife reserve on a tight budget.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Booking is straightforward through our WhatsApp booking system, with flexible departure dates and last-minute availability often possible. We recommend booking 2-3 months in advance for peak season (July-October) to secure preferred dates. Child discounts, group rates, and customizations are available upon request.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Don't miss this opportunity to experience Masai Mara's wonders at budget pricing. Whether you're a first-time safari-goer, solo traveler seeking adventure, or budget-conscious wildlife enthusiast, this 3-day Masai Mara Budget Safari delivers authentic African experiences without breaking the bank. Book now for your 2026 adventure and create memories that will last a lifetime.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "heading", "tag": "h2", "children": [{"type": "text", "text": "Good to know", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Departures: Daily from Nairobi", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Group size: 4-12 people", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}]}}$j$::jsonb, $j$Masai Mara 3 Days Budget Land Cruiser Safari Kenya 2026$j$, $j$Book 3-day Masai Mara budget safari Kenya 2026 from $450. Big Five game drives, shared Land Cruiser, budget camping, all meals. Daily departures from Nairobi.$j$, 'en', v);
      SELECT row_number() OVER (ORDER BY sort_order, id), v, md5(v::text || 'price' || id::text), id, 45000, 45000, 45000, 45000 FROM seasons;
  END IF;
END $do$;
-- budget-tours-data.ts: masai-mara-3-days-superior-budget-shared-land-cruiser-safari
DO $do$ DECLARE v int; BEGIN
  IF NOT EXISTS (SELECT 1 FROM tours WHERE slug = $j$masai-mara-3-days-superior-budget-shared-land-cruiser-safari$j$) THEN
    VALUES ($j$masai-mara-3-days-superior-budget-shared-land-cruiser-safari$j$, false, true, false, false,
      (SELECT id FROM templates WHERE variant = $j$budget$j$::enum_templates_variant ORDER BY id LIMIT 1),
      (SELECT id FROM destinations WHERE slug = $j$kenya$j$),
      3, (SELECT id FROM media WHERE url = $j$/pexels-gil-daix-2046153486-29339542-scaled.jpg$j$ ORDER BY id LIMIT 1),
      NULL, 4, 10) RETURNING id INTO v;
    VALUES ($j$Masai Mara 3 Days Superior Budget Shared Land Cruiser Safari Kenya 2026$j$, $j$Upgraded budget safari with better accommodations and services. Shared Land Cruiser transport, improved camps, enhanced meals. More comfort than basic budget safari. From $730.$j$, $j${"root": {"type": "root", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "paragraph", "children": [{"type": "text", "text": "Experience Masai Mara with enhanced comfort on our Superior Budget Shared Safari Kenya 2026. This 3-day itinerary offers upgraded accommodations, better amenities, and improved services compared to our basic budget safari, while maintaining affordable pricing starting from $730 per person. Perfect for travelers who want more comfort than basic camping but don't want to pay luxury safari prices, this superior budget option represents excellent value for those seeking better accommodations and services without breaking their travel budget.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Our Superior Budget Safari features several key upgrades over our basic budget offering. Accommodations are in better-quality tented camps or lodges with improved facilities such as proper beds with quality bedding, better ensuite bathrooms with hot water reliability, and more comfortable common areas. Meals are upgraded with more variety and better presentation, often including some local specialties and fresh produce. Vehicle comfort is enhanced with newer Land Cruisers and more legroom, while guide expertise remains at our highest standards.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "The journey begins in Nairobi with hotel pick-up in our shared 4x4 Land Cruiser. The drive to Masai Mara includes the same spectacular Great Rift Valley views but with more comfortable seating and possibly fewer passengers per vehicle for extra space. Upon arrival at your superior budget camp, you'll notice immediate differences: better-maintained facilities, more attentive staff, and overall higher comfort levels. These camps typically feature proper dining areas, comfortable lounge spaces, and often swimming pools or better views.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Game drives follow the same excellent schedule as our regular safaris but with potential advantages. Vehicles may be slightly newer or better maintained, and guide experience is often from our senior team. The wildlife viewing remains exceptional - Masai Mara's Big Five, abundant predators, and seasonal Great Migration (July-October) are the main attractions regardless of accommodation level. However, returning to more comfortable accommodations after long game drives significantly enhances your overall experience.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This superior budget option particularly appeals to several traveler types: couples wanting more romantic accommodations, older travelers appreciating better comfort, those celebrating special occasions, or simply anyone who values better amenities after adventurous days in the bush. The price difference of $280 over our basic safari represents excellent value for the upgrades received, particularly when considering that luxury safaris often cost three to five times more for similar wildlife experiences.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Accommodation upgrades are the most noticeable difference. Superior budget camps typically feature larger tents or rooms with proper furniture, better lighting, reliable hot water systems, and more comfortable bedding. Dining experiences are enhanced with better-prepared meals, sometimes including buffet options or a la carte choices rather than fixed menus. Service levels are higher with more attentive staff and often better management oversight.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Transportation upgrades include potentially newer vehicles, better maintenance records, and sometimes fewer passengers per vehicle (though still shared). Guide quality remains excellent as we use our most experienced guides across all our safari levels. What changes is their ability to provide more personalized attention when group sizes are slightly smaller or vehicle configurations allow.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Practical benefits extend throughout the experience. Better accommodations mean more reliable electricity for charging devices, improved Wi-Fi availability (though still limited in remote areas), more comfortable common areas for relaxing between game drives, and often better location within or near the reserve. These seemingly small improvements significantly enhance the overall safari experience, especially after long days of wildlife viewing.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This superior budget safari Kenya 2026 represents smart upgrading for discerning budget travelers. While maintaining the core wildlife experience that makes Masai Mara special, the enhanced comfort levels make the entire journey more enjoyable, particularly for those not accustomed to basic camping or who simply want better value for their money. The additional cost is justified by noticeably better accommodations, improved meals, and overall enhanced service levels.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Booking considerations are similar to our basic safaris, though availability may be more limited due to smaller camp capacities. We recommend booking 2-3 months in advance for peak season (July-October) to secure preferred dates at superior budget camps. Customizations, special requests, and group rates are available with sufficient notice.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Don't miss this opportunity to experience Masai Mara with enhanced comfort at still-affordable pricing. Whether you're celebrating a special occasion, traveling with someone who appreciates better amenities, or simply want to treat yourself to improved comfort after adventurous days in the bush, this 3-day Superior Budget Safari delivers excellent value and enhanced experiences. Book now for your 2026 Masai Mara adventure and enjoy the best of African wildlife with better comfort and service.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "heading", "tag": "h2", "children": [{"type": "text", "text": "Good to know", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Departures: Daily from Nairobi", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Group size: 4-10 people", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}]}}$j$::jsonb, $j$Masai Mara 3 Days Superior Budget Shared Land Cruiser Safari Kenya 2026$j$, $j$Book 3-day Masai Mara superior budget safari Kenya 2026 from $730. Upgraded camps, improved meals, shared Land Cruiser. Better comfort than basic budget.$j$, 'en', v);
      SELECT row_number() OVER (ORDER BY sort_order, id), v, md5(v::text || 'price' || id::text), id, 73000, 73000, 73000, 73000 FROM seasons;
  END IF;
END $do$;
-- budget-tours-data.ts: samburu-3-days-private-safari
DO $do$ DECLARE v int; BEGIN
  IF NOT EXISTS (SELECT 1 FROM tours WHERE slug = $j$samburu-3-days-private-safari$j$) THEN
    VALUES ($j$samburu-3-days-private-safari$j$, false, true, false, false,
      (SELECT id FROM templates WHERE variant = $j$budget$j$::enum_templates_variant ORDER BY id LIMIT 1),
      (SELECT id FROM destinations WHERE slug = $j$kenya$j$),
      3, (SELECT id FROM media WHERE url = $j$/sutirta-budiman-E8JdyPcSA8o-unsplash-5-scaled.jpg$j$ ORDER BY id LIMIT 1),
      NULL, 2, 6) RETURNING id INTO v;
    VALUES ($j$Samburu 3 Days Private Safari Kenya 2026$j$, $j$Private safari to Samburu National Reserve searching for the Special Five. Exclusive vehicle, personalized itinerary, expert guide. Perfect for customized wildlife viewing. From $690.$j$, $j${"root": {"type": "root", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "paragraph", "children": [{"type": "text", "text": "Discover Kenya's unique northern wilderness on our exclusive 3-Day Samburu Private Safari 2026. This personalized adventure, starting from just $690 per person, offers the ultimate in flexibility and customization as you explore Samburu National Reserve with your private vehicle and dedicated guide. Unlike shared group tours, this private safari provides complete control over your daily schedule, itinerary focus, and wildlife viewing priorities. Perfect for families with children, couples seeking romantic adventures, photography enthusiasts needing flexible timing, or anyone wanting personalized attention, this private safari represents exceptional value for experiencing Kenya's distinctive northern ecosystems.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Samburu National Reserve offers completely different wildlife experiences from southern Kenya parks. Located in Kenya's arid north, this reserve is famous for its \"Special Five\" - unique species found only in this region: Grevy's zebra with its elegant narrow stripes, Somali ostrich with distinctive blue-grey legs, reticulated giraffe with geometric coat patterns, gerenuk that stands on hind legs to browse, and Beisa oryx adapted to desert conditions. Beyond these specials, Samburu hosts elephants, lions, leopards, and over 450 bird species, all thriving in the dramatic landscape watered by the Ewaso Nyiro River.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Your private adventure begins in Nairobi, where you'll meet your dedicated guide and private 4x4 vehicle. The journey north reveals Kenya's dramatic landscape changes from central highlands to northern deserts. As a private safari, you control departure time, pace, and stops along the way. This flexibility is particularly valuable for photography, birdwatching, or simply enjoying the scenery at your preferred rhythm.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Upon arrival in Samburu, your private experience truly shines. Want to focus exclusively on finding the Special Five? Interested in extended photography sessions at the river? Prefer leisurely mornings with later starts? Your private safari accommodates all preferences. The flexibility extends to meal times, break durations, and activity choices - you're not bound by group consensus or fixed schedules. This personalized approach significantly enhances wildlife viewing quality, as you can remain at interesting sightings as long as desired.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "The Ewaso Nyiro River forms the lifeblood of Samburu, attracting wildlife throughout the day. Your private guide will strategically plan game drives around river areas where animals congregate, particularly during dry seasons. Early mornings and late afternoons offer optimal viewing as temperatures cool and wildlife becomes more active. Midday hours can be spent relaxing at your lodge or pursuing specific interests like birdwatching or cultural visits.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Cultural interactions with Samburu communities add unique dimensions to your safari. Distinct from southern Maasai, the Samburu people have maintained traditional pastoralist lifestyles in this challenging environment. Your private guide can arrange authentic cultural visits based on your interests and timing preferences, providing insights into desert-adapted lifestyles, traditional knowledge systems, and human-wildlife coexistence strategies unique to northern Kenya.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Photography opportunities abound in Samburu's dramatic landscapes. The arid backdrop, riverine settings, and unique wildlife create distinctive images different from typical safari photos. Your private guide, understanding photographic priorities, will position the vehicle for optimal lighting and backgrounds, wait for behavioral moments, and provide stability for equipment. This photographic support alone can justify choosing a private safari for serious photographers.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This private budget safari represents exceptional value at $690. While more expensive than shared Samburu tours, the benefits of exclusivity, flexibility, and personalization justify the additional cost for many travelers. Families particularly appreciate the ability to adjust schedules for children's needs. Photography enthusiasts value extended time at sightings. Couples enjoy romantic privacy. The private model also allows last-minute itinerary changes based on weather, wildlife reports, or personal interests.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Practical benefits extend throughout your journey. No waiting for other travelers, no compromising on preferences, no fixed meal times, and complete control over daily pacing. Your private vehicle becomes your mobile base, with personal belongings securely stored and readily accessible. Your guide develops understanding of your interests and adapts accordingly throughout the 3-day journey.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This affordable private safari 2026 is perfect for families wanting child-friendly pacing, couples seeking romantic privacy, photography enthusiasts needing flexible timing, travelers with specific wildlife interests (Special Five focus), or anyone preferring personalized attention. The 3-day duration provides comprehensive Samburu exposure while maintaining budget considerations.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Booking private safaris requires discussing specific interests during reservation. We match you with guides experienced in your areas of interest and plan optimal itineraries. Advance booking (1-2 months) is recommended to secure preferred guides and accommodations for private arrangements.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Don't miss this opportunity to experience Kenya's unique northern wilderness on your terms. Whether seeking the Special Five, dramatic desert landscapes, authentic cultural interactions, or simply personalized safari attention, this 3-day Samburu Private Safari delivers exclusive experiences impossible in group settings. Book now for your 2026 northern adventure.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "heading", "tag": "h2", "children": [{"type": "text", "text": "Good to know", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Departures: Daily from Nairobi", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Group size: 2-6 people (private)", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}]}}$j$::jsonb, $j$Samburu 3 Days Private Safari Kenya 2026$j$, $j$Book 3-day Samburu private safari Kenya 2026 from $690. Exclusive northern Kenya adventure with private vehicle, guide, and personalized itinerary. Search for Special Five.$j$, 'en', v);
      SELECT row_number() OVER (ORDER BY sort_order, id), v, md5(v::text || 'price' || id::text), id, 69000, 69000, 69000, 69000 FROM seasons;
  END IF;
END $do$;
-- budget-tours-data.ts: masai-mara-nakuru-4-days-budget-shared-safari
DO $do$ DECLARE v int; BEGIN
  IF NOT EXISTS (SELECT 1 FROM tours WHERE slug = $j$masai-mara-nakuru-4-days-budget-shared-safari$j$) THEN
    VALUES ($j$masai-mara-nakuru-4-days-budget-shared-safari$j$, false, true, false, false,
      (SELECT id FROM templates WHERE variant = $j$budget$j$::enum_templates_variant ORDER BY id LIMIT 1),
      (SELECT id FROM destinations WHERE slug = $j$kenya$j$),
      4, (SELECT id FROM media WHERE url = $j$/1000025509-1.jpg$j$ ORDER BY id LIMIT 1),
      NULL, 4, 12) RETURNING id INTO v;
    VALUES ($j$Masai Mara$j$, $j$Combines Masai Mara's predators with Lake Nakuru's flamingos and rhinos. Shared 4x4 Land Cruiser, budget camps, all meals. Excellent wildlife variety. From $610.$j$, $j${"root": {"type": "root", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "paragraph", "children": [{"type": "text", "text": "Experience the best of Kenya's wildlife diversity on our comprehensive 4-Day Masai Mara - Nakuru Budget Shared Safari Kenya 2026. This affordable tour combines two of Kenya's most iconic and contrasting wildlife destinations, offering exceptional value at just $610 per person. Witness the predator-rich savannahs of Masai Mara alongside the flamingo-filled shores and successful rhino sanctuary of Lake Nakuru National Park - a perfect introduction to Kenya's wildlife variety in one budget-friendly package that delivers outstanding experiences without straining your travel budget.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Your adventure begins in Nairobi as you join fellow travelers in a shared 4x4 Land Cruiser equipped with pop-up roofs for optimal game viewing. The scenic drive to Masai Mara takes you through the dramatic Great Rift Valley, with photo stops at viewpoints showcasing one of Earth's most significant geological features. Upon arrival at Africa's most famous wildlife reserve, you'll check into our selected budget tented camp - comfortable safari accommodation that maintains authentic atmosphere while keeping costs reasonable. These camps feature shared facilities, dining areas, and evening campfires where wildlife stories are exchanged with new friends from around the world.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "In Masai Mara, you'll enjoy approximately 10-12 hours of game drives across multiple sessions timed for optimal wildlife activity. Early morning drives catch predators during their most active periods, with excellent opportunities to witness lion prides, cheetah hunts, and leopard sightings. Afternoon sessions offer golden light photography opportunities as the African sun casts dramatic shadows across the savannah. Your experienced guide will share tracking techniques, animal behavior insights, and conservation knowledge specific to this iconic ecosystem. The Mara's varied habitats - from open grasslands perfect for wildebeest and zebra herds to riverine forests sheltering leopards and elephants - support incredible biodiversity that your guide will help you discover and appreciate.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "The transition to Lake Nakuru National Park introduces dramatically different landscapes and wildlife experiences. As you approach this Rift Valley lake, you'll notice the pink shoreline created by thousands of flamingos - one of Africa's most spectacular wildlife sights. Lake Nakuru's alkaline waters support massive flocks of lesser and greater flamingos, while the surrounding national park hosts one of Kenya's most successful rhino conservation programs. Here you have excellent chances to see both black and white rhino species, along with diverse birdlife numbering over 450 species, Rothschild giraffes, and predators including leopards that favor the yellow acacia forests.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This budget safari Kenya 2026 package represents exceptional value at $610. You receive comprehensive wildlife experiences across two premier parks with completely different ecosystems, professional guiding, comfortable accommodations, all meals, and seamless transportation. The shared group model (4-12 travelers) significantly reduces individual costs while creating social travel experiences perfect for solo travelers, couples, or small groups wanting to meet fellow adventurers. By combining these two destinations, you experience both classic savannah wildlife and unique lake ecosystem spectacles in one efficient itinerary.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Beyond wildlife viewing, educational opportunities abound. Learn about the Great Rift Valley's geological significance, understand different conservation approaches between savannah and lake ecosystems, compare animal adaptations to varied environments, and appreciate Kenya's ecological diversity within relatively compact geography. Optional cultural interactions with Maasai communities provide insights into traditional lifestyles and modern conservation partnerships. At Lake Nakuru, conservation education focuses on successful species recovery programs, particularly for rhinos, demonstrating how dedicated efforts can bring species back from near extinction.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Practical arrangements ensure comfortable travel between these contrasting destinations. Our budget accommodations provide clean, comfortable rooms with ensuite facilities at both locations. Meals are hearty and varied, accommodating dietary needs with advance notice. Transportation in reliable 4x4 Land Cruisers ensures access to prime viewing areas in both parks. Your guide handles all logistics between destinations, allowing you to focus entirely on wildlife experiences rather than travel arrangements.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This affordable Kenya safari 2026 is perfect for first-time visitors wanting comprehensive exposure, wildlife enthusiasts seeking diversity within limited time, budget travelers wanting maximum wildlife experiences per dollar, or photographers wanting both large mammal and bird subjects. The 4-day duration provides balanced time in each park without feeling rushed, while the combination offers excellent wildlife variety that showcases why Kenya remains Africa's premier safari destination.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Booking is straightforward through our WhatsApp booking system, with flexible departure dates and last-minute availability often possible. We recommend booking 2-3 months in advance for peak season (July-October) to secure preferred dates. Child discounts, group rates, and customizations are available upon request for this popular two-park combination.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Don't miss this opportunity to experience Kenya's wildlife highlights at exceptional budget pricing. Whether you're seeking predator action in Masai Mara, flamingo spectacles at Lake Nakuru, comprehensive Kenyan wildlife exposure, or simply the best value safari combining two iconic destinations, this 4-day budget shared safari delivers unforgettable experiences that will leave you with lifelong memories of Africa's magnificent wildlife. Book now for your 2026 adventure and discover why Kenya's diversity makes it the ultimate safari destination.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "heading", "tag": "h2", "children": [{"type": "text", "text": "Good to know", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Departures: Daily from Nairobi", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Group size: 4-12 people", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}]}}$j$::jsonb, $j$Masai Mara$j$, $j$Book 4-day Masai Mara Nakuru budget safari Kenya 2026 from $610. Experience Big Five game drives and flamingo spectacles in one affordable two-park adventure.$j$, 'en', v);
      SELECT row_number() OVER (ORDER BY sort_order, id), v, md5(v::text || 'price' || id::text), id, 61000, 61000, 61000, 61000 FROM seasons;
  END IF;
END $do$;
-- budget-tours-data.ts: masai-mara-naivasha-4-days-budget-shared-safari
DO $do$ DECLARE v int; BEGIN
  IF NOT EXISTS (SELECT 1 FROM tours WHERE slug = $j$masai-mara-naivasha-4-days-budget-shared-safari$j$) THEN
    VALUES ($j$masai-mara-naivasha-4-days-budget-shared-safari$j$, false, true, false, false,
      (SELECT id FROM templates WHERE variant = $j$budget$j$::enum_templates_variant ORDER BY id LIMIT 1),
      (SELECT id FROM destinations WHERE slug = $j$kenya$j$),
      4, (SELECT id FROM media WHERE url = $j$/436772123_840707984764076_1007538712348891897_n.jpg$j$ ORDER BY id LIMIT 1),
      NULL, 4, 12) RETURNING id INTO v;
    VALUES ($j$Masai Mara$j$, $j$Masai Mara predators plus Lake Naivasha boat safari with hippos. Shared 4x4, budget camps, all meals included. Land and water wildlife combination. From $610.$j$, $j${"root": {"type": "root", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "paragraph", "children": [{"type": "text", "text": "Experience the perfect combination of terrestrial and aquatic wildlife adventures on our 4-Day Masai Mara - Naivasha Budget Shared Safari Kenya 2026. This unique itinerary, starting from just $610 per person, combines the predator-rich savannahs of Masai Mara with the freshwater wonders of Lake Naivasha, offering exceptional diversity and value in one affordable package. From tracking the Big Five on classic game drives to cruising among hippo pods on boat safaris, this tour showcases Kenya's wildlife variety across different ecosystems while maintaining budget-friendly pricing perfect for travelers wanting comprehensive experiences without luxury costs.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Your adventure begins in Nairobi as you join fellow wildlife enthusiasts in a shared 4x4 Land Cruiser equipped for optimal game viewing. The journey to Masai Mara takes you through the dramatic Great Rift Valley, with photo stops showcasing one of Earth's most significant geological features. Upon arrival at Africa's most famous wildlife reserve, you'll check into our selected budget tented camp, where the sounds of the African night create authentic safari atmosphere. Masai Mara needs little introduction - its vast savannahs host incredible wildlife densities, including the Big Five, abundant predators, and seasonal Great Migration that represents one of nature's greatest spectacles.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "In Masai Mara, you'll enjoy approximately 10-12 hours of game drives across multiple sessions. Early morning drives catch predators during peak activity hours, with excellent opportunities for lion, leopard, and cheetah sightings. Your experienced guide will share tracking techniques, behavioral insights, and conservation knowledge specific to this iconic ecosystem. The Mara's varied habitats support incredible biodiversity that your guide will help you discover, from open grasslands perfect for photography to riverine forests sheltering elusive species. Game drives are timed for optimal wildlife viewing and photographic conditions, with flexible scheduling to follow animal movements and behaviors.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "The transition to Lake Naivasha introduces completely different experiences centered around freshwater ecosystems. Lake Naivasha is Kenya's highest Rift Valley lake and a freshwater oasis supporting diverse aquatic life. Here, terrestrial game drives give way to boat safaris that bring you face-to-face with hippo pods, diverse bird species including African fish eagles, and aquatic ecosystems impossible to experience from land. The boat safari included in this package offers unique perspectives on wildlife behavior, photography opportunities from water level, and understanding of lake ecology.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Beyond boat safaris, Lake Naivasha offers optional walking safaris on Crescent Island - a rare opportunity to walk among grazing animals in a predator-free environment. This unique experience allows close approaches to giraffes, zebras, and antelopes impossible in national parks, providing completely different interactions with wildlife. The combination of Masai Mara game drives and Naivasha's aquatic/terrestrial experiences creates comprehensive wildlife understanding across different ecosystems.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This budget safari Kenya 2026 package represents exceptional value at $610. You receive diverse wildlife experiences across two completely different environments, professional guiding, comfortable accommodations, included boat safari, and all meals. The shared group model (4-12 travelers) significantly reduces individual costs while creating social travel experiences perfect for solo travelers, couples, or small groups. By combining these destinations, you experience both classic African savannah safaris and unique freshwater adventures in one efficient itinerary.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Educational opportunities abound across both ecosystems. Learn about predator-prey relationships in Masai Mara, understand aquatic ecosystems and hippo behavior at Naivasha, compare animal adaptations to different environments, and appreciate Kenya's ecological diversity. Conservation education covers both savannah and lake protection challenges, while cultural interactions (optional) provide insights into different human relationships with these environments.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Practical arrangements ensure comfortable transitions between ecosystems. Our budget accommodations provide clean, comfortable rooms with ensuite facilities at both locations. Meals are hearty and varied, accommodating dietary needs. Transportation in reliable 4x4 Land Cruisers ensures access to all areas, while the included boat safari offers safe aquatic exploration. Your guide handles all logistics between destinations, allowing complete focus on wildlife experiences.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This affordable Kenya safari 2026 is perfect for travelers wanting diverse experiences, families enjoying both game drives and boat adventures, photography enthusiasts seeking varied subjects, first-time visitors wanting comprehensive exposure, or anyone appreciating ecosystem comparisons. The 4-day duration provides balanced time in each environment without feeling rushed, while the combination offers exceptional variety showcasing Kenya's ecological richness.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Booking is straightforward through our WhatsApp system with flexible departure dates. We recommend booking 2-3 months in advance for peak season (July-October). Child discounts, group rates, and customizations are available upon request for this popular land-water combination.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Don't miss this opportunity to experience Kenya's wildlife diversity across ecosystems at exceptional budget pricing. Whether seeking predator action in Masai Mara, hippo encounters at Naivasha, comprehensive wildlife understanding, or simply unique safari experiences combining land and water adventures, this 4-day budget shared safari delivers unforgettable memories of Africa's magnificent wildlife in varied environments. Book now for your 2026 adventure.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "heading", "tag": "h2", "children": [{"type": "text", "text": "Good to know", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Departures: Daily from Nairobi", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Group size: 4-12 people", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}]}}$j$::jsonb, $j$Masai Mara$j$, $j$Book 4-day Masai Mara Naivasha budget safari Kenya 2026 from $610. Game drives and boat safari with hippos in one affordable land-water adventure from Nairobi.$j$, 'en', v);
      SELECT row_number() OVER (ORDER BY sort_order, id), v, md5(v::text || 'price' || id::text), id, 61000, 61000, 61000, 61000 FROM seasons;
  END IF;
END $do$;
-- budget-tours-data.ts: masai-mara-nakuru-naivasha-5-days-shared-land-cruiser-safari
DO $do$ DECLARE v int; BEGIN
  IF NOT EXISTS (SELECT 1 FROM tours WHERE slug = $j$masai-mara-nakuru-naivasha-5-days-shared-land-cruiser-safari$j$) THEN
    VALUES ($j$masai-mara-nakuru-naivasha-5-days-shared-land-cruiser-safari$j$, false, true, false, false,
