      (SELECT id FROM destinations WHERE slug = $j$kenya$j$),
      5, (SELECT id FROM media WHERE url = $j$/grace-nandi-KzxdgYVkSdY-unsplash-1-scaled.jpg$j$ ORDER BY id LIMIT 1),
      NULL, 4, 12) RETURNING id INTO v;
    VALUES ($j$Masai Mara$j$, $j$Three iconic parks: Masai Mara predators, Lake Nakuru flamingos, Naivasha hippo boat ride. Shared Land Cruiser, budget camps, all meals. Excellent wildlife variety. From $680.$j$, $j${"root": {"type": "root", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "paragraph", "children": [{"type": "text", "text": "Experience Kenya's wildlife diversity at its best on our comprehensive 5-Day Masai Mara - Nakuru & Naivasha Shared Land Cruiser Safari Kenya 2026. This exceptional three-park adventure, starting from just $680 per person, combines Kenya's most iconic wildlife destinations into one affordable package offering maximum wildlife variety and value. From the predator-rich savannahs of Masai Mara to the flamingo-filled shores of Lake Nakuru and the hippo-populated waters of Lake Naivasha, this tour showcases Kenya's ecological richness across different ecosystems while maintaining budget-friendly pricing perfect for travelers wanting comprehensive exposure without luxury costs.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Your journey begins in Nairobi as you join fellow wildlife enthusiasts in a shared 4x4 Land Cruiser equipped with pop-up roofs for optimal game viewing. The scenic drive to Masai Mara takes you through the dramatic Great Rift Valley, with photo stops at viewpoints showcasing one of Earth's most significant geological features. Masai Mara National Reserve needs little introduction - it's Africa's wildlife crown jewel, famous for high predator densities, spectacular Great Migration (July-October), and classic savannah landscapes that define the African safari experience. Here you'll spend quality time tracking the Big Five, observing predator behaviors, and immersing in one of the world's premier wildlife destinations.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "The transition to Lake Nakuru National Park introduces dramatically different wildlife spectacles. This alkaline lake ecosystem attracts thousands of flamingos creating pink shorelines visible from distance, while the park's highly successful rhino sanctuary offers excellent viewing of both black and white rhino species. The contrast between Mara's savannahs and Nakuru's lake environment demonstrates Kenya's ecological diversity within relatively compact geography. Your guide will explain the different conservation approaches, animal adaptations, and ecological relationships specific to each ecosystem.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Lake Naivasha provides the third distinct ecosystem experience - freshwater adventures centered around Kenya's highest Rift Valley lake. The included boat safari offers unique perspectives on hippo behavior, fish eagle hunting techniques, and aquatic ecosystems impossible to experience from land. Optional walking safaris on Crescent Island (additional cost) allow terrestrial experiences among grazing animals without predators, providing close wildlife approaches unique to this environment. This combination of Masai Mara game drives, Nakuru flamingo/rhino viewing, and Naivasha aquatic experiences creates comprehensive wildlife understanding across Kenya's varied ecosystems.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This budget safari Kenya 2026 package represents exceptional value at $680. You receive diverse wildlife experiences across three premier destinations, professional guiding, comfortable accommodations, included boat safari, and all meals. The shared group model (4-12 travelers) significantly reduces individual costs while creating social travel experiences perfect for solo travelers, couples, or small groups. By combining these three destinations, you experience savannah, alkaline lake, and freshwater ecosystems in one efficient itinerary that maximizes wildlife variety per day and dollar.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Educational opportunities abound across all three ecosystems. Learn about predator-prey relationships in Masai Mara, flamingo biology and rhino conservation at Lake Nakuru, aquatic ecosystems and hippo behavior at Naivasha, and compare animal adaptations across different environments. Conservation education covers varied challenges and successes across ecosystems, while cultural interactions (optional) provide insights into different human relationships with these environments. This comprehensive educational approach transforms wildlife viewing into deeper ecological understanding.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Practical arrangements ensure comfortable transitions between ecosystems. Our budget accommodations provide clean, comfortable rooms with ensuite facilities across all locations. Meals are hearty and varied, accommodating dietary needs with advance notice. Transportation in reliable 4x4 Land Cruisers ensures access to prime viewing areas, while the included boat safari offers safe aquatic exploration. Your guide handles all logistics between destinations, allowing complete focus on wildlife experiences rather than travel arrangements.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "This affordable Kenya safari 2026 is perfect for first-time visitors wanting comprehensive exposure, wildlife enthusiasts seeking maximum diversity, photography enthusiasts needing varied subjects, families enjoying different experiences, or travelers wanting the best value multi-park safari. The 5-day duration provides balanced time across three ecosystems without feeling rushed, while the combination offers exceptional variety showcasing why Kenya remains Africa's premier safari destination.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Booking is straightforward through our WhatsApp system with flexible departure dates. We recommend booking 2-3 months in advance for peak season (July-October) to secure preferred dates. Child discounts, group rates, and customizations are available upon request for this popular three-park combination.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Don't miss this opportunity to experience Kenya's wildlife diversity across multiple ecosystems at exceptional budget pricing. Whether seeking predator action in Masai Mara, flamingo spectacles at Lake Nakuru, hippo encounters at Naivasha, comprehensive wildlife understanding, or simply maximum variety in one affordable package, this 5-day shared Land Cruiser safari delivers unforgettable memories of Africa's magnificent wildlife across varied environments. Book now for your 2026 adventure and discover why Kenya's ecological diversity makes it the ultimate safari destination.", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "heading", "tag": "h2", "children": [{"type": "text", "text": "Good to know", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Departures: Daily from Nairobi", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}, {"type": "paragraph", "children": [{"type": "text", "text": "Group size: 4-12 people", "detail": 0, "format": 0, "mode": "normal", "style": "", "version": 1}], "direction": "ltr", "format": "", "indent": 0, "textFormat": 0, "version": 1}]}}$j$::jsonb, $j$Masai Mara$j$, $j$Book 5-day Masai Mara Nakuru Naivasha safari Kenya 2026 from $680. Big Five, flamingos, hippos boat ride in one affordable three-park adventure from Nairobi.$j$, 'en', v);
      SELECT row_number() OVER (ORDER BY sort_order, id), v, md5(v::text || 'price' || id::text), id, 68000, 68000, 68000, 68000 FROM seasons;
