    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$19d7d77201a89ebfb865242e$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Pick up at Hotel and drive to Masai Mara National Reserve$j$, $j$You will be picked up at your hotel/place of stay in Nairobi at 7:00 am and your driver guide will meet and greet you and afterwards escort you to the car and commence drive southwest to Masai Mara. Have a stopover at the great Rift Valley view point enroute where you will have a breathtaking view of the floor of the Rift Valley. Arrive for check in and hot lunch at the camp. After lunch, you may opt for an optional Maasai village visit at an extra cost of 30 USD per person. Return at dusk for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$19d7d77201a89ebfb865242e$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$a2ed424531a0d30cb6560782$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day exploring Masai Mara National Reserve$j$, $j$This day you will depart after an early breakfast to Masai Mara Reserve for morning and afternoon game viewing drives. Picnic lunches will be served as you relax under a tree as you enjoy breathtaking views of the vast landscape and its beauty. Spend the day looking for the big 5 and an abundant of wildlife that the Mara has to offer. You will also visit the Mara River where we are hopeful that you will have a chance to witness the great wildebeest migration as it happens. Thereafter you will return to the camp for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$a2ed424531a0d30cb6560782$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$72241c117a1d0001bd6fe4a7$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Nairobi$j$, $j$After breakfast check out and you may opt for an optional Maasai village visit, where you will interact with the Maasai community and learn about their way of life and culture at an extra cost of 30 USD per person. Later on commence drive to Nairobi with lunch on the way. Upon arrival you will be dropped off at Nairobi CBD.$j$, 'en', $j$72241c117a1d0001bd6fe4a7$j$);
