    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$c0a1074aa4e2239e10f5b129$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What is the cost of a 3-day Masai Mara budget safari in Kenya 2026?$j$, $j$Our cheap Masai Mara safari starts from $450 per person for shared group tours. This all-inclusive price covers transport, park fees, accommodation, meals, game drives, and professional guiding. Additional costs may include optional activities, tips, and personal expenses.$j$, 'en', $j$c0a1074aa4e2239e10f5b129$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$dc5001b07c3aff0ce10cd7ae$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is this affordable Kenya safari suitable for families with children?$j$, $j$Yes, our budget group safaris are family-friendly! Children aged 6+ can join with adult supervision. We recommend private safaris for families with younger children or specific needs. Child discounts (30% off) available for ages 6-12 sharing with adults.$j$, 'en', $j$dc5001b07c3aff0ce10cd7ae$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$d49faed68fbd469010836ad1$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$When is the best time for Masai Mara budget safari 2026?$j$, $j$July to October offers the best wildlife viewing with the Great Migration. However, our safaris operate year-round with excellent wildlife sightings possible anytime. January-February and June-October are dry seasons with concentrated wildlife at water sources.$j$, 'en', $j$d49faed68fbd469010836ad1$j$);
