    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$4c45ef3341684307a6c44489$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Items not mentioned in inclusions$j$, 'en', $j$4c45ef3341684307a6c44489$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$821ca1f78f1f036c7e4f4ee9$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What makes this 'superior' compared to your basic budget safari?$j$, $j$This safari features better accommodations (upgraded tents/better facilities), improved meal quality and variety, potentially newer vehicles, senior guides, and enhanced overall service. While maintaining budget pricing, it offers noticeable comfort improvements over our basic $450 safari.$j$, 'en', $j$821ca1f78f1f036c7e4f4ee9$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$5eb3de8ccf308548844dd97b$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is the wildlife viewing different on this superior safari?$j$, $j$The wildlife viewing experience is identical - same park, same game drives. The difference is in comfort levels: better accommodations to return to, improved meals, enhanced vehicle comfort, and more experienced guides providing deeper interpretation.$j$, 'en', $j$5eb3de8ccf308548844dd97b$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$22716524398296af55ce965d$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Who should choose this superior budget option?$j$, $j$Perfect for travelers wanting better comfort without luxury prices, couples seeking more romantic accommodations, older travelers appreciating amenities, those celebrating special occasions, or anyone who values returning to better facilities after adventurous days.$j$, 'en', $j$22716524398296af55ce965d$j$);
