    INSERT INTO tours_locales (title, summary, description, seo_title, seo_description, _locale, _parent_id)
    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$f82108750646b576efd52b77$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive from Nairobi to Samburu$j$, $j$Your driver guide will pick you up at the airport or your hotel in Nairobi. After meet and greet, he will escort you to your car and commence drive to Samburu National Reserve arriving for lunch at the camp. After check in and lunch, you will embark on an afternoon game drive or an optional visit to a local Samburu village and return to the camp at dusk for dinner and overnight stay at Lion’s Cave Camp Samburu.$j$, 'en', $j$f82108750646b576efd52b77$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$56ded649b4249e24be4fc051$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day Game drives in Samburu National Reserve$j$, $j$After early breakfast at the camp, join your safari driver guide and depart for full day game viewing drive with picnic lunch boxes to Samburu National Reserve, famous for its truly wild semi-arid landscape, and the large concentration of wild animals and bird-life. Together with the adjoining Shaba and Buffalo Springs national reserves, Samburu is popular for hosting the rare Northern-Kenya animal species (Gerenuk, Reticulated Giraffe, Grevy’s zebra, Beisa Oryx and Somali Ostrich) which are not found in the other popular parks and reserves in Kenya. It is also home to all the African big cats (lion, cheetah and leopard), alongside other big game including elephants, buffaloes, warthogs, hippos, impala, water-buck and many others. Samburu is also a renowned bird watching haven, with hundreds of bird species resident here. These include kingfisher, bee-eaters, tawny eagle, guinea-fowl, yellow throated spur-fowl, lilac-breasted roller, red-billed hornbill, secretary bird, Verreaux’s eagle, superb starling, yellow-billed hornbill and vultures. Dinner and overnight stay at Lion’s Cave Camp Samburu.$j$, 'en', $j$56ded649b4249e24be4fc051$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$3b55be7e723c3c5dfe375e2f$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Samburu to Nairobi$j$, $j$After breakfast, check out and onward departure back to Nairobi. Arrive Nairobi in the afternoon where you will be dropped off at your hotel or free onward transfer to the airport for your flight home.$j$, 'en', $j$3b55be7e723c3c5dfe375e2f$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (1, v, $j$cccc06a686f35fb317018322$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Private 4x4 vehicle and exclusive guide throughout safari$j$, 'en', $j$cccc06a686f35fb317018322$j$);
