    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$7259927cbde515a172da397e$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Items not mentioned in inclusions$j$, 'en', $j$7259927cbde515a172da397e$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$4e68309a74e9df5c11cfcb66$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What are the 'Special Five' in Samburu?$j$, $j$Samburu's Special Five are unique species not found in southern Kenya parks: 1) Grevy's zebra (narrow stripes), 2) Somali ostrich (blue-grey legs), 3) Reticulated giraffe (geometric pattern), 4) Gerenuk (stands on hind legs to browse), and 5) Beisa oryx (desert-adapted antelope). Seeing all five is a special achievement for wildlife enthusiasts.$j$, 'en', $j$4e68309a74e9df5c11cfcb66$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$4482d574dc8462ab2388d806$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Why choose a private safari for Samburu?$j$, $j$Private safaris offer complete flexibility for Special Five tracking, customized timing for river wildlife viewing, personalized photography opportunities, and ability to adjust for weather/animal movements. Essential for serious photographers, families with children, or travelers with specific interests in northern species.$j$, 'en', $j$4482d574dc8462ab2388d806$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$27dc1b41c3ce4784e061e192$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$How does Samburu differ from Masai Mara?$j$, $j$Samburu features arid northern landscapes vs Mara's savannahs, unique Special Five vs Big Five, Ewaso Nyiro river ecosystem vs Mara River, and Samburu culture vs Maasai culture. It offers completely different experiences focusing on desert-adapted wildlife and dramatic scenery.$j$, 'en', $j$27dc1b41c3ce4784e061e192$j$);
    INSERT INTO tours (slug, generate_slug, published, featured, sample, template_id, destination_id, duration_days, hero_image_id, facts_pace, facts_group_size_min, facts_group_size_max)
