    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$41015fc6bcd88d9d2907fc80$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive Nairobi to Masai Mara$j$, $j$You will be picked up at your hotel/place of stay in Nairobi at 7:00 am and your driver guide will meet and greet you and afterwards escort you to the car and commence drive southwest to Masai Mara. Have a stopover at the great Rift Valley view point enroute where you will have a breathtaking view of the floor of the Rift Valley. Arrive for check in and hot lunch at the camp. After lunch, embark on an evening game drive to Masai Mara in search for the big 5 among other wildlife. Return for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$41015fc6bcd88d9d2907fc80$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$e687eb249bd91e892e51e4db$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day exploring Masai Mara National Reserve$j$, $j$This day you will depart after an early breakfast to Masai Mara Reserve for morning and afternoon game viewing drives. Picnic lunches will be served as you relax under a tree as you enjoy breathtaking views of the vast landscape and its beauty. Spend the day looking for the big 5 and an abundant of wildlife that the Mara has to offer. You will also visit the Mara River where we are hopeful that you will have a chance to witness the great wildebeest migration as it happens. Thereafter you will return to the camp for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$e687eb249bd91e892e51e4db$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$312635a3848824a5949c9d1d$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Naivasha$j$, $j$After breakfast check out and proceed to drive to Naivasha with lunch on the way. ‘Lake Naivasha offers an accessible and captivating safari experience in Kenya’s Rift Valley. Known for its tranquil waters and abundant wildlife, this freshwater lake provides a unique adventure for nature enthusiasts and travelers seeking a serene escape.’ Arrive at Naivasha in the evening for dinner and overnight at Leisure Apex.$j$, 'en', $j$312635a3848824a5949c9d1d$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$1cc375d7330bcb1a9b367db6$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Lake Naivasha Boat Ride & Crescent Island Visit – Drive to Nairobi$j$, $j$After breakfast, depart for Lake Naivasha for a scenic boat ride, offering excellent views of hippos and diverse birdlife. Continue with a guided walking safari at Crescent Island, where you can walk among giraffes, zebras, wildebeest and antelopes in a beautiful, predator-free setting. Thereafter, begin your drive to Nairobi. Upon arrival you will be dropped off at Nairobi CBD.$j$, 'en', $j$1cc375d7330bcb1a9b367db6$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (1, v, $j$6cef2a9f754eaa7875d9884a$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Affordable combination of Masai Mara savannahs and Lake Nakuru lake ecosystem$j$, 'en', $j$6cef2a9f754eaa7875d9884a$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (2, v, $j$a85d9f93e6640ef12c924114$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Big Five game drives in Masai Mara National Reserve$j$, 'en', $j$a85d9f93e6640ef12c924114$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (3, v, $j$9b70dc51ff6a3b6270c69b10$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Flamingo spectacle and rhino sanctuary at Lake Nakuru National Park$j$, 'en', $j$9b70dc51ff6a3b6270c69b10$j$);
