    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (7, v, $j$9e66af6c0091b71d3c213331$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Single room supplement ($120 extra if available)$j$, 'en', $j$9e66af6c0091b71d3c213331$j$);
    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$d753f5c03b42649d8f98deac$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Items not mentioned in inclusions$j$, 'en', $j$d753f5c03b42649d8f98deac$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$a538a74d112094c3361ed6ab$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What is included in the $610 price for this 4-day safari?$j$, $j$The price includes shared 4x4 Land Cruiser transport, professional guide, all park fees, game drives, full-board meals, budget accommodations, bottled water, Nairobi transfers, and government taxes. Excluded are international flights, visas, insurance, tips, optional activities, alcohol, and personal expenses.$j$, 'en', $j$a538a74d112094c3361ed6ab$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$771de82cead3958cb696d594$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$How likely are we to see rhinos at Lake Nakuru?$j$, $j$Very high probability! Lake Nakuru National Park has one of Kenya's most successful rhino sanctuaries with both black and white rhino species. Our experienced guides know their territories and have excellent sighting records. The park is specifically managed for rhino conservation with dedicated anti-poaching efforts.$j$, 'en', $j$771de82cead3958cb696d594$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$3e8228be97d508589d1228b3$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What's the travel time between Masai Mara and Lake Nakuru?$j$, $j$Approximately 5-6 hours driving time, depending on road conditions and stops. We schedule this travel during midday when wildlife is less active, breaking the journey with lunch and comfort stops. The drive itself showcases Kenya's changing landscapes from savannah to highlands.$j$, 'en', $j$3e8228be97d508589d1228b3$j$);
    INSERT INTO tours (slug, generate_slug, published, featured, sample, template_id, destination_id, duration_days, hero_image_id, facts_pace, facts_group_size_min, facts_group_size_max)
    INSERT INTO tours_locales (title, summary, description, seo_title, seo_description, _locale, _parent_id)
    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$7db71fe65a33fc9a9245c466$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive Nairobi to Masai Mara$j$, $j$You will be picked up at your hotel/place of stay in Nairobi at 7:00 am and your driver guide will meet and greet you and afterwards escort you to the car and commence drive southwest to Masai Mara. Have a stopover at the great Rift Valley view point enroute where you will have a breathtaking view of the floor of the Rift Valley. Arrive for check in and hot lunch at the camp. After lunch, embark on an evening game drive to Masai Mara in search for the big 5 among other wildlife. Return for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$7db71fe65a33fc9a9245c466$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$a1438895dd42f5fb53dcfdd6$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day exploring Masai Mara National Reserve$j$, $j$This day you will depart after an early breakfast to Masai Mara Reserve for morning and afternoon game viewing drives. Picnic lunches will be served as you relax under a tree as you enjoy breathtaking views of the vast landscape and its beauty. Spend the day looking for the big 5 and an abundant of wildlife that the Mara has to offer. You will also visit the Mara River where we are hopeful that you will have a chance to witness the great wildebeest migration as it happens. Thereafter you will return to the camp for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$a1438895dd42f5fb53dcfdd6$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$08ac17eaa74cb0f3b01081a2$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Nakuru$j$, $j$After breakfast check out and you may opt to visit the Maasai village, where you will interact with the Maasai community and learn about their way of life and culture at 30 USD per person. Later on, proceed drive to Nakuru with lunch on the way. Arrive at Nakuru in the evening for dinner and overnight at Buraha Zenoni Hotel & Resort.$j$, 'en', $j$08ac17eaa74cb0f3b01081a2$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$899d6bfcd1f8beed54ff4701$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Morning Game drive in Lake Nakuru National Park and transfer to Nairobi$j$, $j$After an early breakfast, depart for a morning game drive at Lake Nakuru National Park where we hope you will have the sight of flamingos. Have your cameras ready as here you will see lots of rhinos. Later on exit the park with lunch on the way. Continue drive to Nairobi and you will be dropped off at Nairobi CBD on arrival.$j$, 'en', $j$899d6bfcd1f8beed54ff4701$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (1, v, $j$9dc2aaa35d4300f1b642391e$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Affordable combination of Masai Mara savannahs and Lake Naivasha freshwater ecosystem$j$, 'en', $j$9dc2aaa35d4300f1b642391e$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (2, v, $j$5ef79d98cb4f2a6fa1c560fc$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Big Five game drives in Masai Mara National Reserve$j$, 'en', $j$5ef79d98cb4f2a6fa1c560fc$j$);
