    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (4, v, $j$9e0412cb8b010d9aacac185a$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Optional activities (Crescent Island walk $20, village visits)$j$, 'en', $j$9e0412cb8b010d9aacac185a$j$);
