    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (7, v, $j$914057a89f38d6f64325855a$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Single room supplement ($120 extra if available)$j$, 'en', $j$914057a89f38d6f64325855a$j$);
    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$baf7dc15fd117e1676203b25$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Items not mentioned in inclusions$j$, 'en', $j$baf7dc15fd117e1676203b25$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$50123551741ca1f57704c903$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What makes Lake Naivasha different from other safari destinations?$j$, $j$Lake Naivasha offers freshwater boat safaris (included) for close hippo and bird viewing, plus optional walking safaris where you can walk among wildlife - unique experiences impossible in national parks. It provides aquatic perspectives complementing traditional game drives.$j$, 'en', $j$50123551741ca1f57704c903$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$b77fa81d9fb5b0e4c8ed9a18$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is the boat safari safe with hippos present?$j$, $j$Yes, we use experienced boat captains who maintain safe distances from hippo pods while providing excellent viewing. Hippos are respected but not feared when proper precautions are followed. Life jackets are provided, and boats are maintained to highest safety standards.$j$, 'en', $j$b77fa81d9fb5b0e4c8ed9a18$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$730720ef9c553d40fcd19780$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Can we do both Masai Mara and Naivasha in 4 days comfortably?$j$, $j$Absolutely! Our itinerary is carefully designed with optimal timing: 2 days in Mara for comprehensive game viewing, travel day with boat safari, and final morning at Naivasha. The combination works perfectly within 4 days, offering diverse experiences without feeling rushed.$j$, 'en', $j$730720ef9c553d40fcd19780$j$);
