    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$11f811aa1ae032fd29987c2c$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Pick up at Hotel and drive to Masai Mara National Reserve$j$, $j$You will be picked up at your hotel/place of stay in Nairobi at 7:00 am and your driver guide will meet and greet you and afterwards escort you to the car and commence drive southwest to Masai Mara. Have a stopover at the great Rift Valley view point enroute where you will have a breathtaking view of the floor of the Rift Valley. Arrive for check in and hot lunch at the camp. After lunch, embark on an evening game drive to Masai Mara in search for the big 5 among other wildlife. Return at dusk for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$11f811aa1ae032fd29987c2c$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$8fec9748bcf03a124ccca322$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day exploring Masai Mara National Reserve$j$, $j$This day you will depart after an early breakfast to Masai Mara Reserve for morning and afternoon game viewing drives. Picnic lunches will be served as you relax under a tree as you enjoy breathtaking views of the vast landscape and its beauty. Spend the day looking for the big 5 and an abundant of wildlife that the Mara has to offer. You will also visit the Mara River where we are hopeful that you will have a chance to witness the great wildebeest migration as it happens. Thereafter you will return to the camp for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$8fec9748bcf03a124ccca322$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$c02b22859da6abee619dc768$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Optional Maasai village visit and drive to Nakuru$j$, $j$After breakfast, check out of the camp and you may decide to engage in the optional visit of the Maasai village at an extra cost of 30 USD and here interact with Maasai community and learn about their way of life. Thereafter depart for Nakuru enjoying lunch on the way. Arrive for dinner and overnight at Buraha Zenoni Hotel & Resort.$j$, 'en', $j$c02b22859da6abee619dc768$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$dc757cd8091c0ea1de18791a$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Morning Game drive in Nakuru National Park and depart for Naivasha$j$, $j$After breakfast depart for a morning game drive in Lake Nakuru National Park. Exit the park at around noon and proceed drive to Naivasha with lunch on the way. Arrive in Naivasha and you can enjoy an optional boat ride at an extra cost of 40 USD per person which your driver guide will assist to organize for you. Dinner and overnight at Leisure Apex Hotel.$j$, 'en', $j$dc757cd8091c0ea1de18791a$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (5, v, $j$99424decd3b2a3b42e5428a7$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Lake Naivasha Boat Ride & Crescent Island Visit – Drive to Nairobi$j$, $j$After breakfast, depart for Lake Naivasha for a scenic boat ride, offering excellent views of hippos and diverse birdlife. Continue with a guided walking safari at Crescent Island, where you can walk among giraffes, zebras, wildebeests, and antelopes in a beautiful, predator-free setting. Thereafter, begin your drive to Nairobi with lunch en route. Upon arrival in Nairobi you will be dropped off at Nairobi CBD.$j$, 'en', $j$99424decd3b2a3b42e5428a7$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (1, v, $j$dd38c001e48aa27c6336a858$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Comprehensive three-park safari covering Masai Mara, Lake Nakuru, and Lake Naivasha$j$, 'en', $j$dd38c001e48aa27c6336a858$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (2, v, $j$0209433f2eeecb7ce8d48ba9$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Big Five game drives in Masai Mara National Reserve$j$, 'en', $j$0209433f2eeecb7ce8d48ba9$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (3, v, $j$58b316b5a05e8794a9bf219a$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Flamingo spectacle and rhino sanctuary at Lake Nakuru National Park$j$, 'en', $j$58b316b5a05e8794a9bf219a$j$);
