    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (7, v, $j$c1c571563dea328e9b678213$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Single room supplement ($160 extra if available)$j$, 'en', $j$c1c571563dea328e9b678213$j$);
    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$4a270c5ea5d5a941c10880c7$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Items not mentioned in inclusions$j$, 'en', $j$4a270c5ea5d5a941c10880c7$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$1e97fa8b34bc8b3accf909dc$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Why choose this three-park safari over two-park options?$j$, $j$This safari offers maximum wildlife variety: Masai Mara for Big Five predators, Lake Nakuru for flamingos/rhinos, and Lake Naivasha for hippos/boat safari. It's perfect for first-time visitors wanting comprehensive exposure or travelers wanting diverse experiences in one affordable package.$j$, 'en', $j$1e97fa8b34bc8b3accf909dc$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$18ff20f154e012d77d4be9bb$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$How much driving is involved between these three parks?$j$, $j$Approximate driving times: Nairobi to Masai Mara (5-6h), Masai Mara to Nakuru (5-6h), Nakuru to Naivasha (2-3h), Naivasha to Nairobi (2-3h). We schedule driving during less optimal wildlife viewing times and include scenic stops. The total driving is well balanced with ample game viewing time.$j$, 'en', $j$18ff20f154e012d77d4be9bb$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$1fd618f4b4c04b47ed610703$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is 5 days sufficient for three parks?$j$, $j$Yes, our itinerary is carefully designed with optimal timing: 2 full days in Mara, 1 day in Nakuru with travel, and 1 day in Naivasha with travel. While longer would be ideal, this 5-day package provides comprehensive experiences in all three parks without feeling overly rushed for budget-conscious travelers.$j$, 'en', $j$1fd618f4b4c04b47ed610703$j$);
