    INSERT INTO tours_locales (title, summary, description, seo_title, seo_description, _locale, _parent_id)
    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$3128a75aa59426294a58ad5b$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Pick up at Hotel and drive to Masai Mara National Reserve$j$, $j$You will be picked up at your hotel/place of stay in Nairobi at 7:00 am and your driver guide will meet and greet you and afterwards escort you to the car and commence drive southwest to Masai Mara. Have a stopover at the great Rift Valley view point enroute where you will have a breathtaking view of the floor of the Rift Valley. Arrive for check in and hot lunch at the camp. After lunch, embark on an evening game drive to Masai Mara in search for the big 5 among other wildlife. Return at dusk for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$3128a75aa59426294a58ad5b$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$61dd2124e875ea2a8374aac3$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day exploring Masai Mara National Reserve$j$, $j$This day you will depart after an early breakfast to Masai Mara Reserve for morning and afternoon game viewing drives. Picnic lunches will be served as you relax under a tree as you enjoy breathtaking views of the vast landscape and its beauty. Spend the day looking for the big 5 and an abundant of wildlife that the Mara has to offer. You will also visit the Mara River where we are hopeful that you will have a chance to witness the great wildebeest migration as it happens. Thereafter you will return to the camp for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$61dd2124e875ea2a8374aac3$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$eb901549af91da36afc22747$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Nakuru$j$, $j$After breakfast check out and you may opt to visit the Maasai village, where you will interact with the Maasai community and learn about their way of life and culture at 30 USD per person. Later on, proceed drive to Nakuru with lunch on the way. Arrive at Nakuru in the evening for dinner and overnight at Buraha Zenoni Hotel & Resort.$j$, 'en', $j$eb901549af91da36afc22747$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$aed076e3249cdb0bb3e3ec25$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Morning Game drive in Lake Nakuru National Park and drive to Amboseli$j$, $j$After an early breakfast, depart for a morning game drive at Lake Nakuru National Park where we hope you will have the sight of flamingos. Have your cameras ready as here you will see lots of rhinos. Exit the park at around noon and you will continue drive to Amboseli arriving for dinner and overnight stay at Manjaro Tented Camp.$j$, 'en', $j$aed076e3249cdb0bb3e3ec25$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (5, v, $j$5dc3405916ddce1bfda34711$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Explore Amboseli National Park$j$, $j$You will wake up to amazing views of Mount Kilimanjaro if the weather permits. On this day, you will embark on morning and afternoon game drives in this wonderful park where Mount Kilimanjaro’s background offers good photographic scenery. It is coupled with an abundant of wildlife zebras, the Big 5, herds of elephant tusks and the prolific birdlife in this African wilderness park. Return for dinner and overnight stay at Manjaro Tented Camp.$j$, 'en', $j$5dc3405916ddce1bfda34711$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (6, v, $j$5552ac0123b7914f547476fd$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Nairobi$j$, $j$After breakfast, check out and embark on your journey back to Nairobi and upon arrival you will be dropped off at Nairobi City Market or your hotel in Nairobi CBD (Central Business District).$j$, 'en', $j$5552ac0123b7914f547476fd$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (1, v, $j$2b750178efc0b168fdad7a9e$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Comprehensive coverage of Kenya's top three wildlife parks$j$, 'en', $j$2b750178efc0b168fdad7a9e$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (2, v, $j$c834eaa63a85d80dfc4e2567$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Big Five game drives in Masai Mara National Reserve$j$, 'en', $j$c834eaa63a85d80dfc4e2567$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (3, v, $j$1af93de4c64481addbea2364$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Flamingo spectacle and rhino sanctuary at Lake Nakuru National Park$j$, 'en', $j$1af93de4c64481addbea2364$j$);
