    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (7, v, $j$ad9f297bb212bfc332c42bea$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Single room supplement ($200 extra if available)$j$, 'en', $j$ad9f297bb212bfc332c42bea$j$);
    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$03d9f02fd3ba78d96f7e502a$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Items not mentioned in inclusions$j$, 'en', $j$03d9f02fd3ba78d96f7e502a$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$e9ac0e896dd44332d09a14d1$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Why include Amboseli in this three-park safari?$j$, $j$Amboseli offers unique elephant viewing against Kilimanjaro backdrop - iconic African imagery impossible elsewhere. Combined with Mara's predators and Nakuru's flamingos, it creates complete Kenya experience: savannah predators, lake birds, and elephants with mountain views.$j$, 'en', $j$e9ac0e896dd44332d09a14d1$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$fff8ebcaec066671323ffaf8$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$How much driving is involved on this 6-day safari?$j$, $j$Significant driving: Nairobi to Mara (5-6h), Mara to Nakuru (5-6h), Nakuru to Amboseli (7-8h), Amboseli to Nairobi (4-5h). We schedule driving during less optimal wildlife viewing times. While substantial, the driving showcases Kenya's diverse landscapes between premier parks.$j$, 'en', $j$fff8ebcaec066671323ffaf8$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$9736edeccbb08b7f05edb3c0$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is Mount Kilimanjaro always visible from Amboseli?$j$, $j$Visibility depends on weather conditions. Clear days (especially early morning) offer spectacular views. Cloud cover can obscure the mountain, but we time game drives for best visibility chances. Even without clear views, Amboseli's elephant herds are exceptional.$j$, 'en', $j$9736edeccbb08b7f05edb3c0$j$);
