    INSERT INTO tours_locales (title, summary, description, seo_title, seo_description, _locale, _parent_id)
    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$5c86abc70494db7ce9b8b665$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive Nairobi to Masai Mara$j$, $j$You will be picked up at your hotel/place of stay in Nairobi at 7:00 am and your driver guide will meet and greet you and afterwards escort you to the car and commence drive southwest to Masai Mara. Have a stopover at the great Rift Valley view point enroute where you will have a breathtaking view of the floor of the Rift Valley. Arrive for check in and hot lunch at the camp. After lunch, embark on an evening game drive to Masai Mara in search for the big 5 among other wildlife. Return for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$5c86abc70494db7ce9b8b665$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$6b7ab3e3d723791b14c29e5e$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day exploring Masai Mara National Reserve$j$, $j$This day you will depart after an early breakfast to Masai Mara Reserve for morning and afternoon game viewing drives. Picnic lunches will be served as you relax under a tree as you enjoy breathtaking views of the vast landscape and its beauty. Spend the day looking for the big 5 and an abundant of wildlife that the Mara has to offer. You will also visit the Mara River where we are hopeful that you will have a chance to witness the great wildebeest migration as it happens. Thereafter you will return to the camp for dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$6b7ab3e3d723791b14c29e5e$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$999733ac801150dffc8d701b$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Nakuru$j$, $j$After breakfast check out and you may opt to visit the Maasai village, where you will interact with the Maasai community and learn about their way of life and culture at 30 USD per person. Later on, proceed drive to Nakuru with lunch on the way. Arrive at Nakuru in the evening for dinner and overnight at Buraha Zenoni Hotel & Resort.$j$, 'en', $j$999733ac801150dffc8d701b$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$716365921db9affe4f72f936$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Morning Game drive at Lake Nakuru National Park and drive to Naivasha$j$, $j$Enjoy a morning game drive at the great Lake Nakuru National Park. Thereafter check out and enjoy lunch on the way. Drive to Naivasha for dinner and overnight at Leisure Apex Hotel.$j$, 'en', $j$716365921db9affe4f72f936$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (5, v, $j$14ac376d51e6a294a72e2e4c$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Lake Naivasha Boat Ride & Crescent Island Visit – Drive to Amboseli National Park$j$, $j$After breakfast, depart for Lake Naivasha for a scenic boat ride, offering excellent views of hippos and diverse birdlife. Continue with a guided walking safari at Crescent Island, where you can walk among giraffes, zebras, wildebeest and antelopes in a beautiful, predator-free setting. Thereafter, begin your drive to Amboseli National Park, with lunch en route. Arrive in the evening for dinner and an overnight stay at Manjaro Tented Camp.$j$, 'en', $j$14ac376d51e6a294a72e2e4c$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (6, v, $j$93efaff3e9975e1c0cb33a58$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Game drive in Amboseli National Park$j$, $j$Very early in the morning, weather permitting you should be able to see the spectacular views of the snowcapped Mt Kilimanjaro towering at a distance. Proceed for a morning game drive in the park where you will enjoy Amboseli Jumbos among other wildlife. You will also visit the observation point and have a look at the park from here. Dinner and overnight stay at Manjaro Tented Camp.$j$, 'en', $j$93efaff3e9975e1c0cb33a58$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (7, v, $j$e71f46ab7cbe62186e71fbc7$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Nairobi$j$, $j$After breakfast, check out and commence drive to Nairobi with lunch on the way. Upon arrival you will be dropped off at Nairobi CBD.$j$, 'en', $j$e71f46ab7cbe62186e71fbc7$j$);
