    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$127f3ff09974ca3e72f45997$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Items not mentioned in inclusions$j$, 'en', $j$127f3ff09974ca3e72f45997$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$7996a47fd147d5a30071cca9$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Why is this called the 'Best of Kenya' safari?$j$, $j$This itinerary covers Kenya's four most important and diverse wildlife areas: Masai Mara (Big Five/savannah), Lake Nakuru (flamingos/rhinos), Lake Naivasha (hippos/boat safari), and Amboseli (elephants/Kilimanjaro). It represents the most comprehensive Kenya wildlife experience available at budget pricing.$j$, 'en', $j$7996a47fd147d5a30071cca9$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$4b1da9b8af0c8fea30fd8da7$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$How much driving is involved in this 7-day circuit?$j$, $j$Significant driving: Nairobi to Mara (5-6h), Mara to Nakuru (5-6h), Nakuru to Naivasha (2-3h), Naivasha to Amboseli (6-7h), Amboseli to Nairobi (4-5h). We schedule driving during less optimal wildlife viewing times. While substantial, the journey showcases Kenya's diverse landscapes between premier parks.$j$, 'en', $j$4b1da9b8af0c8fea30fd8da7$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$6864b211d7e5b95183f8be24$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is this safari suitable for first-time visitors to Africa?$j$, $j$Perfect for first-timers! This comprehensive circuit provides excellent introduction to African wildlife across different ecosystems. The 7-day duration allows proper acclimatization, while shared group model offers social support. Many first-time visitors choose this as their ideal introduction to Kenya.$j$, 'en', $j$6864b211d7e5b95183f8be24$j$);
