    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$c2dd378e1ddac7bb03763e99$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Pick up from JKIA Airport and drive to Samburu$j$, $j$Upon arrival and after you are done with the immigration procedures, your driver guide will pick you up at the airport. After meet and greet, he will escort you to your car and commence drive to Samburu National Reserve arriving for lunch at Lion’s Cave Camp Samburu. After check in and lunch, you will go for an afternoon game drive at 16:00hrs and return to the camp at dusk for dinner and overnight stay at Lion’s Cave Camp Samburu.$j$, 'en', $j$c2dd378e1ddac7bb03763e99$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$00b5aee45950ff15398858df$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day Game drives in Samburu National Reserve$j$, $j$After early breakfast at the lodge at 07:00 am, join your safari driver guide and depart for full day game viewing drive with picnic lunch boxes to Samburu National Reserve. You will explore the park and its special beautiful sceneries with lots of animals and birds. Dinner and overnight stay at Lion’s Cave Camp Samburu.$j$, 'en', $j$00b5aee45950ff15398858df$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$63afe7322ea76e03a191edb0$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive from Samburu to Olpejeta$j$, $j$After breakfast depart for Olpejeta. “Located between the Aberdares and Mount Kenya, Ol Pejeta hosts 2 of the planet’s last remaining northern white rhinos. It’s also home to southern white rhinos, black rhinos, scavengers and the only place in Kenya where you can see chimpanzees. There is an equator marker within the conservation area where you can take photos and you may engage in additional activities such as lion tracking, bush and bird walks and rhino rides.” Later on return for dinner and overnight stay at Comfort Garden Sweet Waters.$j$, 'en', $j$63afe7322ea76e03a191edb0$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$6ed105c0750eb6ec66f954bd$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Ol Pejeta to Naivasha$j$, $j$After early breakfast at the lodge at 07:00 am, check out and join your safari driver guide and depart for Naivasha arriving in time for lunch and check in. In the afternoon, you will enjoy a boat ride in Lake Naivasha in search for hippos and the birdlife. Dinner and overnight stay at Eseriani The Resort.$j$, 'en', $j$6ed105c0750eb6ec66f954bd$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (5, v, $j$e12397871e104cef98f713ea$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Lake Naivasha Hell’s Gate Tour & drive to Maasai Mara$j$, $j$After breakfast, check out and drive to Hell’s Gate National Park. Upon arrival, you will enjoy bike rides cycling to the gorges and back as you explore the park. Exit the park and proceed drive to Maasai Mara through the scenic Rift Valley with amazing views of Mt. Longonot with lunch on the way. Arrive at the camp in the evening for check in, dinner and overnight stay at Rhino Tourist Camp.$j$, 'en', $j$e12397871e104cef98f713ea$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (6, v, $j$cfbe4fcf9f3f8467c7dbc3df$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day exploring Maasai Mara Reserve$j$, $j$This day you will depart after an early breakfast to Maasai Mara Reserve for full day game viewing drives. Picnic lunches will be served as you relax under a tree as you see the vast landscape and its beauty. Spend the whole day looking for the big five and we are hopeful you will see almost all if not all of the big five among many animals. Thereafter you will return to the camp for dinner and overnight at Rhino Tourist Camp.$j$, 'en', $j$cfbe4fcf9f3f8467c7dbc3df$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (7, v, $j$37cac8b9b7c7ee7af2c7897d$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Maasai Mara to Nairobi$j$, $j$After breakfast, check out and drive to Nairobi and upon arrival, you will be dropped at Jomo Kenyatta International Airport (Nairobi) for your flight home.$j$, 'en', $j$37cac8b9b7c7ee7af2c7897d$j$);
