    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (7, v, $j$7025ffc31d5228cfeda40074$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Single room supplement ($350 extra if available)$j$, 'en', $j$7025ffc31d5228cfeda40074$j$);
    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$7470c01726998c166bce9518$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Photography equipment (bring your own)$j$, 'en', $j$7470c01726998c166bce9518$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$916a6525d02b813368fdcc1e$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What makes this a 'Big Five' focused safari?$j$, $j$This safari prioritizes lion, leopard, elephant, buffalo, and rhino sightings through specialized tracking, extended game drives, strategic park selection, and expert guides. Every aspect - timing, locations, guide training - optimizes Big Five opportunities rather than general wildlife viewing.$j$, 'en', $j$916a6525d02b813368fdcc1e$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$a0e8b6a9bff76dced33b5ea5$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What are the chances of seeing all Big Five?$j$, $j$Very high with our specialized approach. We achieve over 90% success rate for all five species on this itinerary. Strategic park combinations (Mara for lion/leopard, Nakuru for rhino, Amboseli for elephants) and expert tracking maximize probabilities, though wildlife remains unpredictable.$j$, 'en', $j$a0e8b6a9bff76dced33b5ea5$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$2ab18401f6aa580e5189fca7$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is this suitable for photographers?$j$, $j$Excellent for photographers! We optimize vehicle positioning, lighting consideration, waiting times for behaviors, and access to prime locations. While not a dedicated photo safari, the Big Five focus naturally aligns with photographic goals for iconic species portraits.$j$, 'en', $j$2ab18401f6aa580e5189fca7$j$);
    INSERT INTO tours (slug, generate_slug, published, featured, sample, template_id, destination_id, duration_days, hero_image_id, facts_pace, facts_group_size_min, facts_group_size_max)
    INSERT INTO tours_locales (title, summary, description, seo_title, seo_description, _locale, _parent_id)
    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$61e8b19a3a33f59c05e54392$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Nairobi to Masai Mara$j$, $j$Depart Nairobi early in the morning (around 7:00 am) from your hotel/place of stay. Your driver-guide will meet you, escort you to the vehicle and begin the drive southwest towards the Masai Mara. En route, stop at the Great Rift Valley viewpoint for stunning panoramic views of the Rift Valley floor. Arrive in the Mara in time for lunch and check-in. After lunch, enjoy relaxation at the camp. In the evening you can embark on an optional visit to the Maasai village where you will interact with the Maasai community as you learn about their way of life and culture. Dinner and overnight stay at Veilscape Mara Camp.$j$, 'en', $j$61e8b19a3a33f59c05e54392$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$9858ebb3e51bb0c24a45933a$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day exploring Masai Mara National Reserve$j$, $j$A full day spent exploring Masai Mara National Reserve. Depart after an early breakfast for morning game drive, followed by a picnic lunch under a tree in the reserve. In the afternoon, continue game viewing drives. Keep an eye out for the Big 5 as well as other wild animals such as zebras, giraffes and an abundant of birdlife. Return to the camp at dusk for dinner and overnight stay at Veilscape Mara Camp.$j$, 'en', $j$9858ebb3e51bb0c24a45933a$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$c85a7535ae41d3530ec5f1ac$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Big 5 Game viewing drives in Masai Mara$j$, $j$Another full day in Masai Mara. After breakfast, embark on morning and afternoon game drives, further exploring different areas of the Mara. Between drives enjoy picnic lunch and rest. Return to the camp at dusk for dinner and overnight stay at Veilscape Mara Camp.$j$, 'en', $j$c85a7535ae41d3530ec5f1ac$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$a272c74994e47a874ece99a8$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Nakuru$j$, $j$After breakfast, check out and depart toward Nakuru. Continue drive, with lunch along the way. Arrive in Nakuru in the evening for dinner and overnight stay at Buraha Zenoni Hotel & Resort.$j$, 'en', $j$a272c74994e47a874ece99a8$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (5, v, $j$2c04d8b3050fbccb3bf42389$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Morning game drive at Lake Nakuru National Park and drive to Naivasha$j$, $j$Morning game drive at Lake Nakuru National Park. After exploring Nakuru, check out and drive toward Naivasha. Lunch en route. Arrive at Naivasha for dinner and overnight stay at Leisure Apex Hotel.$j$, 'en', $j$2c04d8b3050fbccb3bf42389$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (6, v, $j$9e022fdfa4d640497288b407$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Hell's Gate visit and drive to Amboseli National Park$j$, $j$After breakfast, proceed with a visit to Hell's Gate National Park for a walking safari. There is also an optional boat ride on Lake Naivasha at an extra cost of 40 USD per person. After these activities, depart toward Amboseli National Park, with lunch along the way. Arrive in Amboseli in the evening for dinner and overnight at Manjaro Tented Camp.$j$, 'en', $j$9e022fdfa4d640497288b407$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (7, v, $j$02cf687eda7854c220d19f1c$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Game drive in Amboseli National Park$j$, $j$Very early morning, wake up (weather permitting) to amazing views of snowcapped Mount Kilimanjaro glowing in the sunrise light. Then go on a morning game drive in Amboseli, including a visit to the observation point for panoramic views of the park and its wildlife (especially elephants). Return at dusk for dinner and overnight stay at Manjaro Tented Camp.$j$, 'en', $j$02cf687eda7854c220d19f1c$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (8, v, $j$2e887bd8f4f6363aa123d0c6$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Nairobi$j$, $j$After breakfast, check out and commence the drive back to Nairobi. Lunch along the way. Upon arrival in Nairobi, you will be dropped off at your hotel/place of stay or JKIA International Airport for your flight back home.$j$, 'en', $j$2e887bd8f4f6363aa123d0c6$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (1, v, $j$94158019822799adaf4699f9$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Extended 8-day duration for comprehensive Big Five tracking$j$, 'en', $j$94158019822799adaf4699f9$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (2, v, $j$abba1fb05164039c9577ac50$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Specialized guides with advanced tracking expertise$j$, 'en', $j$abba1fb05164039c9577ac50$j$);
