    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$753300ddf3a687c49d4bf3a8$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Photography equipment (bring your own)$j$, 'en', $j$753300ddf3a687c49d4bf3a8$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$1d9c018f826883105bb125d9$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$How does this 8-day safari differ from the 7-day Big Five version?$j$, $j$The extra day provides strategic flexibility: time to return to productive locations, follow animal movements over multiple days, wait for specific behaviors, or focus on challenging species. This transforms sightings from brief encounters to meaningful observations with pattern recognition and behavioral understanding.$j$, 'en', $j$1d9c018f826883105bb125d9$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$1f9c54c3103742c5f0a7b711$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Who should choose this extended Big Five safari?$j$, $j$Serious wildlife enthusiasts wanting comprehensive understanding, photographers building professional portfolios, travelers with singular African opportunities wanting maximum experiences, or anyone valuing depth over breadth in wildlife viewing. The additional cost is justified by significantly enhanced experiences beyond basic sightings.$j$, 'en', $j$1f9c54c3103742c5f0a7b711$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$25d6fe9da2c2c30ef25c06e2$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What photography advantages does the extended time provide?$j$, $j$Time for different lighting conditions, various behaviors, multiple angles, environmental contexts, returning to locations at optimal times, waiting for specific actions, and building comprehensive portfolios rather than snapshot collections. Essential for serious wildlife photography beyond basic tourist shots.$j$, 'en', $j$25d6fe9da2c2c30ef25c06e2$j$);
    INSERT INTO tours (slug, generate_slug, published, featured, sample, template_id, destination_id, duration_days, hero_image_id, facts_pace, facts_group_size_min, facts_group_size_max)
    INSERT INTO tours_locales (title, summary, description, seo_title, seo_description, _locale, _parent_id)
    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$48c1965cc3e836370668f792$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Pick up from JKIA airport and drive to Samburu$j$, $j$Upon arrival and after you are done with the immigration procedures, your driver guide will pick you up at the airport. After meet and greet, he will escort you to your car and commence drive to Samburu national Reserve arriving for lunch at Lion’s Cave Camp Samburu. After check in and lunch, you will go for an afternoon game drive at 16:00hrs and return to the camp before dusk for dinner and overnight stay at Lion’s Cave Camp Samburu.$j$, 'en', $j$48c1965cc3e836370668f792$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$22e6b18c17a37318029947b5$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day Game drives in Samburu National Reserve$j$, $j$After early breakfast at the camp, join your safari driver guide and depart for full day game viewing drive with picnic lunch boxes to Samburu National Reserve. You will explore the park and its special beautiful sceneries with lots of animals and birds. Dinner and overnight stay at Lion’s Cave Camp Samburu.$j$, 'en', $j$22e6b18c17a37318029947b5$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$2c12cd16946189ef5be2b456$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive from Samburu to Olpejeta$j$, $j$After breakfast depart for Olpejeta. “Located between the Aberdares and Mount Kenya, Ol Pejeta hosts 2 of the planet’s last remaining northern white rhinos. It’s also home to southern white rhinos, black rhinos, scavengers and the only place in Kenya where you can see chimpanzees. There is an equator marker within the conservation area where you can take photos.” Dinner and overnight stay at Comfort Gardens Sweetwaters.$j$, 'en', $j$2c12cd16946189ef5be2b456$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$7c92dd1a07c68272e1e84f10$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Lake Nakuru National Park$j$, $j$After breakfast check out and proceed drive to Nakuru with lunches on the way. Lake Nakuru is “A beautiful wildlife haven”. On the floor of the Great Rift Valley, surrounded by wooded and bushy grassland, lies the beautiful. Arrive at Nakuru for an afternoon game drive in Lake Nakuru National Park where we hope you will have the sight of flamingos. Have your cameras ready as here you will see lots of Rhinos. Later on exit the park for dinner and overnight stay at Buraha Zenoni Hotel & Resort.$j$, 'en', $j$7c92dd1a07c68272e1e84f10$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (5, v, $j$fe76f983b44aaf71ecd43cb1$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Nakuru to Amboseli National Park$j$, $j$After breakfast, depart Nakuru for Amboseli National Park with lunch on the way arriving for dinner and overnight stay at Manjaro Tented Camp.$j$, 'en', $j$fe76f983b44aaf71ecd43cb1$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (6, v, $j$909565a1f41192bd06acc0d2$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full day exploring Amboseli National Park$j$, $j$You will wake up to amazing views of Mount Kilimanjaro if the weather permits. On this day, you will embark on a full day game drive in this wonderful park where Mount Kilimanjaro’s background offers good photographic scenery. It is coupled with animals on the ground, the Big Five, herds of elephants, and the prolific birdlife in this African wilderness park. Return for dinner and overnight stay at Manjaro Tented Camp.$j$, 'en', $j$909565a1f41192bd06acc0d2$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (7, v, $j$612034eed75d474703d441f2$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive to Naivasha$j$, $j$After breakfast, enjoy a morning game drive in Amboseli National Park and later on depart for Naivasha arriving for lunch. In the afternoon enjoy a boat ride in Naivasha in search for hippos and the birdlife as well as a guided walk at the Crescent Island where you will spot animals roaming at close proximity. Dinner and overnight stay at Leisure Apex Hotel.$j$, 'en', $j$612034eed75d474703d441f2$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (8, v, $j$b71e829c6c3329591a7650a7$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Drive Naivasha to Masai Mara$j$, $j$After breakfast, check out and commence drive to Masai Mara. Have a stopover at the great Rift Valley view point where you will have a breathtaking view of the floor of the Rift Valley. Arrive for check in and hot lunch at the camp. After lunch, visit Maasai village where you will interact with Maasai and learn their way of life and culture. Dinner and overnight stay will be at Rhino Tourist Camp.$j$, 'en', $j$b71e829c6c3329591a7650a7$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (9, v, $j$0f8f5726d4749834964cd27c$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Masai Mara full day exploring the reserve$j$, $j$This day you will depart after an early breakfast to Masai Mara Reserve for full day game viewing drives. Picnic lunches will be served as you relax under a tree as you see the vast landscape and its beauty. Spend the whole day looking for the big 5 and we are hopeful you will see almost all if not all of the big five among many animals. Thereafter you will return to the camp for dinner and overnight at Rhino Tourist Camp.$j$, 'en', $j$0f8f5726d4749834964cd27c$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (10, v, $j$cee6c3590493429e9dd9e3b1$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Masai Mara to Nairobi$j$, $j$After breakfast, check out and depart for Nairobi with lunch on the way. Upon arrival you will be dropped off at the airport or your hotel in Nairobi.$j$, 'en', $j$cee6c3590493429e9dd9e3b1$j$);
