    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$5dcab611b10b2034af856db8$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Items not mentioned in inclusions$j$, 'en', $j$5dcab611b10b2034af856db8$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$e65d573443379fe2c4579f8a$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Why is this called 'Kenya's Best' safari?$j$, $j$This itinerary covers Kenya's five most important and diverse wildlife areas: Samburu (northern Special Five), Lake Nakuru (flamingos/rhinos), Lake Naivasha (hippos/boat safari), Masai Mara (Big Five/savannah), and Amboseli (elephants/Kilimanjaro). It represents the most comprehensive Kenya wildlife experience available at budget pricing.$j$, 'en', $j$e65d573443379fe2c4579f8a$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$ab77bf4044f49855aa0819cb$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$How much driving is involved in this 10-day circuit?$j$, $j$Substantial driving covering Kenya's geographical diversity: Nairobi-Samburu (5-6h), Samburu-Nakuru (6-7h), Nakuru-Mara (5-6h), Mara-Naivasha (5-6h), Naivasha-Amboseli (6-7h), Amboseli-Nairobi (4-5h). We schedule driving strategically with breaks and scenic stops. The journey itself showcases Kenya's diverse landscapes.$j$, 'en', $j$ab77bf4044f49855aa0819cb$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$93824248936f79cef05fa718$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is this safari suitable for first-time visitors?$j$, $j$Excellent for first-timers with sufficient time (10 days). The comprehensive coverage provides complete Kenya introduction. However, shorter 5-7 day safaris might be better for those testing safari interest or with limited time. This extended version is ideal for serious wildlife enthusiasts or those wanting thorough exposure.$j$, 'en', $j$93824248936f79cef05fa718$j$);
