    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$bb504bf0d86a1d43dfce109c$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Nairobi to Masai Mara - Afternoon Game Drive$j$, $j$Early morning pickup from your Nairobi hotel or airport (by 7:00 AM). Depart for Masai Mara via the scenic Great Rift Valley, with a stop at the viewpoint for breathtaking photos. Continue to Narok town for a brief refreshment stop. Arrive at your budget camp in Masai Mara by early afternoon for check-in and lunch. After settling in, embark on your first afternoon game drive at 4:00 PM, exploring the reserve's eastern sectors. Return to camp before dusk for dinner and overnight stay at Rhino Tourist Camp or similar budget accommodation.$j$, 'en', $j$bb504bf0d86a1d43dfce109c$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$dbde5b836dfa9599732966f2$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full Day Masai Mara Game Drives$j$, $j$Early morning game drive starting at 6:30 AM to catch predators at their most active. Return to camp for breakfast around 9:00 AM. After breakfast, depart with packed lunches for a full day of game viewing in the reserve. Your guide will take you to prime wildlife areas, potentially including the Mara River (depending on season and animal movements). Spend the day searching for the Big Five and observing the Mara's diverse ecosystem. Enjoy your picnic lunch at a scenic spot within the reserve. Continue game viewing throughout the afternoon, returning to camp around 5:30 PM. Dinner and overnight at your camp.$j$, 'en', $j$dbde5b836dfa9599732966f2$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$eb33fd4798506e440ae4b7c0$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Morning Game Drive & Return to Nairobi$j$, $j$Early breakfast at the camp followed by a final morning game drive (7:00 AM - 10:00 AM), giving you last opportunities for wildlife sightings and photography. Return to camp for check-out by 10:30 AM. Depart Masai Mara for Nairobi, with a lunch stop in Narok town. Arrive in Nairobi by late afternoon (approximately 4:00-5:00 PM). Drop-off at your hotel or Jomo Kenyatta International Airport for your onward travel.$j$, 'en', $j$eb33fd4798506e440ae4b7c0$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (1, v, $j$79d9de6d5339b25361ab7b8f$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Three extensive game drives (afternoon, full day, morning) totaling 12-15 hours$j$, 'en', $j$79d9de6d5339b25361ab7b8f$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (2, v, $j$6abf1532c36ad699900ba692$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Big Five viewing opportunities in Africa's most famous wildlife reserve$j$, 'en', $j$6abf1532c36ad699900ba692$j$);
