    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$eec80c4b066ec074846034db$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is 3 days enough for Masai Mara safari?$j$, $j$Yes, 3 days provides a comprehensive Masai Mara experience. While longer stays allow more wildlife sightings, our optimized itinerary includes 12-15 hours of game drives across different times of day, covering key areas of the reserve. Most travelers see the Big Five (except sometimes rhino) and abundant other wildlife. It's perfect for those with limited time wanting essential Mara experience.$j$, 'en', $j$eec80c4b066ec074846034db$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$40b3c2bf33081c72a42b03be$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What is the best time for this 3-day Masai Mara safari?$j$, $j$Masai Mara offers excellent wildlife viewing year-round. July-October is peak for witnessing the Great Migration river crossings. January-March is dry season with good game viewing and fewer crowds. April-June and November are low season with potential rain but lush landscapes and lower prices. Our safari operates weekly throughout the year.$j$, 'en', $j$40b3c2bf33081c72a42b03be$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$00b756d92d2d35800a9219fe$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What type of accommodation is included in the budget camp?$j$, $j$Budget camps like Rhino Tourist Camp offer comfortable permanent tents or basic bandas with proper beds, mosquito nets, and en-suite bathrooms with hot showers. Facilities include dining area, campfire place, and secure surroundings. While not luxury, they provide authentic safari experience with essential comforts at affordable pricing.$j$, 'en', $j$00b756d92d2d35800a9219fe$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (4, v, $j$da15da261eefbcc07f3268d8$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Can solo travelers book this safari?$j$, $j$Absolutely! Solo travelers are welcome. We arrange same-gender room sharing to avoid single supplements. If you prefer private room, single supplement of $120 applies (subject to availability). The shared group experience makes this safari social and cost-effective for solo travelers.$j$, 'en', $j$da15da261eefbcc07f3268d8$j$);
