    INSERT INTO tours_locales (title, summary, description, seo_title, seo_description, _locale, _parent_id)
    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$b4eea9eeffa90d708f891a4a$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Nairobi to Masai Mara - Afternoon Game Drive$j$, $j$Early morning pickup from your Nairobi hotel or airport (by 7:00 AM). Depart for Masai Mara via the scenic Great Rift Valley, stopping at the viewpoint for breathtaking photos. Continue to Narok town for refreshments. Arrive at your budget camp in Masai Mara by early afternoon for check-in and lunch. After settling in, embark on your first afternoon game drive at 4:00 PM, exploring the reserve's eastern sectors. Return to camp before dusk for dinner and overnight at Rhino Tourist Camp or similar.$j$, 'en', $j$b4eea9eeffa90d708f891a4a$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$4bd21d79e1382bf9454a3063$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full Day Masai Mara Game Drives$j$, $j$Early morning game drive starting at 6:30 AM to witness predators at their most active. Return to camp for breakfast around 9:00 AM. Depart with packed lunches for a full day of game viewing. Your guide will take you to prime wildlife areas, potentially including the Mara River (seasonal). Spend the day searching for the Big Five and observing diverse wildlife. Enjoy picnic lunch at a scenic spot. Continue game viewing throughout the afternoon, returning to camp around 5:30 PM. Dinner and overnight at your camp.$j$, 'en', $j$4bd21d79e1382bf9454a3063$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$00d11a60fb0c8b278be128be$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Masai Mara to Lake Nakuru$j$, $j$Early breakfast followed by a final morning game drive in Masai Mara (7:00 AM - 10:00 AM). Return to camp for check-out by 10:30 AM. Depart Masai Mara for Lake Nakuru, with lunch en route. Arrive at Lake Nakuru National Park in the afternoon for game drive focusing on flamingos (seasonal), rhinos, and other wildlife. The park is famous for its alkaline lake attracting thousands of flamingos and its successful rhino sanctuary. Exit the park for dinner and overnight at Buraha Zenoni Hotel & Resort or similar.$j$, 'en', $j$00d11a60fb0c8b278be128be$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$540f6b110dd236f173a5eab0$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Lake Nakuru to Amboseli National Park$j$, $j$After breakfast, enjoy a morning game drive in Lake Nakuru National Park for additional wildlife viewing. Depart Nakuru for Amboseli National Park, with lunch en route. The journey offers scenic views of Kenyan countryside. Arrive at your camp near Amboseli in the late afternoon. If time permits, enjoy sunset views of Mount Kilimanjaro. Dinner and overnight at Manjaro Tented Camp or similar budget accommodation.$j$, 'en', $j$540f6b110dd236f173a5eab0$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (5, v, $j$620e5246d874f9790f8b7eee$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full Day Amboseli National Park$j$, $j$Wake up early for potential clear views of Mount Kilimanjaro at sunrise. After breakfast, embark on full day game drives in Amboseli National Park with packed lunches. The park is famous for its large elephant herds, spectacular Kilimanjaro backdrop, and diverse wildlife including lions, cheetahs, giraffes, zebras, and abundant birdlife. Your guide will take you to prime viewing areas including swamp areas where elephants gather. Enjoy picnic lunch with Kilimanjaro views (weather permitting). Continue afternoon game viewing before returning to camp around 5:30 PM. Dinner and overnight at your camp.$j$, 'en', $j$620e5246d874f9790f8b7eee$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (6, v, $j$09b3022fb59e40592c6d7872$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Morning Game Drive & Return to Nairobi$j$, $j$Early breakfast followed by final morning game drive in Amboseli (7:00 AM - 10:00 AM), giving last opportunities for elephant sightings and Kilimanjaro photographs. Return to camp for check-out by 10:30 AM. Depart Amboseli for Nairobi, with lunch stop en route. Arrive in Nairobi by late afternoon (approximately 4:00-5:00 PM). Drop-off at your hotel or Jomo Kenyatta International Airport for onward travel.$j$, 'en', $j$09b3022fb59e40592c6d7872$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (1, v, $j$ec9b3cf7cb35d321b793a874$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Two full days in Masai Mara for comprehensive Big Five viewing$j$, 'en', $j$ec9b3cf7cb35d321b793a874$j$);
