    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (7, v, $j$a1a3f462968d8baed038bfa5$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Personal expenses and souvenirs$j$, 'en', $j$a1a3f462968d8baed038bfa5$j$);
    INSERT INTO tours_excluded (_order, _parent_id, id) VALUES (8, v, $j$5f2ecd2e564c80ee52d3f7f3$j$); INSERT INTO tours_excluded_locales (text, _locale, _parent_id) VALUES ($j$Items of personal nature$j$, 'en', $j$5f2ecd2e564c80ee52d3f7f3$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$85f1f7089ff63c2a896d432d$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is 6 days enough for this three-park circuit?$j$, $j$Yes, 6 days provides balanced time for this classic circuit. The itinerary allocates: 2 days Masai Mara (optimal for wildlife), 1 day Lake Nakuru (compact park), and 1.5 days Amboseli (elephant focus). Travel days include game drives, maximizing wildlife time. It's perfect for comprehensive Kenyan introduction without extended commitment.$j$, 'en', $j$85f1f7089ff63c2a896d432d$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$0939d995ee8a010d2c908700$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What is the best season for this 6-day safari?$j$, $j$Year-round with seasonal highlights: July-October for Mara migration; January-February for clear Kilimanjaro views; November-December for birdwatching at Nakuru. Dry seasons (Jun-Oct, Jan-Feb) offer best wildlife viewing. Wet seasons (Mar-May, Nov) have lush landscapes and fewer tourists.$j$, 'en', $j$0939d995ee8a010d2c908700$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$917c42c6979274d3a2cf8214$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$How much driving is involved between parks?$j$, $j$Approximate driving times: Nairobi-Mara (5-6h), Mara-Nakuru (5-6h), Nakuru-Amboseli (6-7h), Amboseli-Nairobi (4-5h). We schedule drives strategically with breaks and scenic stops. Travel itself showcases Kenya's diverse landscapes from Rift Valley to Kilimanjaro foothills.$j$, 'en', $j$917c42c6979274d3a2cf8214$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (4, v, $j$3028bc8f74a46d258d3da05d$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Can we see Mount Kilimanjaro clearly from Amboseli?$j$, $j$Visibility depends on weather. Early mornings (6-9 AM) typically offer clearest views, especially June-September and January-February. Afternoon clouds often obscure the peak. Our itinerary maximizes morning viewing opportunities with early game drives when Kilimanjaro is most visible.$j$, 'en', $j$3028bc8f74a46d258d3da05d$j$);
