    INSERT INTO tours_pricing_matrix (_order, _parent_id, id, season_id, p2, p4, p6, p8)
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (1, v, $j$39bf1ef17595c6a2e8b360ab$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Nairobi to Masai Mara - Afternoon Game Drive$j$, $j$Early morning pickup from your Nairobi hotel or airport (by 7:00 AM). Depart for Masai Mara via the scenic Great Rift Valley, stopping at the viewpoint for panoramic photos. Continue to Narok town for refreshments. Arrive at your budget camp in Masai Mara by early afternoon for check-in and lunch. After settling in, embark on your first afternoon game drive at 4:00 PM, exploring the reserve's wildlife-rich sectors. Return to camp before dusk for dinner and overnight at Rhino Tourist Camp or similar.$j$, 'en', $j$39bf1ef17595c6a2e8b360ab$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (2, v, $j$0306972ec191c3d624fdac09$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Full Day Masai Mara Game Drives$j$, $j$Early morning game drive starting at 6:30 AM to witness predators during their most active hours. Return to camp for breakfast around 9:00 AM. Depart with packed lunches for a full day of game viewing in Masai Mara. Your guide will take you to prime wildlife areas, potentially including the Mara River (seasonal). Spend the day searching for the Big Five and observing diverse wildlife behaviors. Enjoy picnic lunch at a scenic spot within the reserve. Continue afternoon game viewing before returning to camp around 5:30 PM. Dinner and overnight at your camp.$j$, 'en', $j$0306972ec191c3d624fdac09$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (3, v, $j$81938e0fa1469095616c6fe3$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Masai Mara to Lake Naivasha - Boat Safari$j$, $j$After breakfast, enjoy a final morning game drive in Masai Mara (7:00 AM - 10:00 AM) for last wildlife opportunities. Return to camp for check-out by 10:30 AM. Depart Masai Mara for Lake Naivasha, with lunch en route. Arrive at Lake Naivasha in the afternoon and check into your accommodation. At 4:00 PM, enjoy an included boat safari on Lake Naivasha, offering close encounters with hippos, diverse bird species, and scenic lake views. Return to shore before dusk. Dinner and overnight at Leisure Apex Hotel or similar lakeside accommodation.$j$, 'en', $j$81938e0fa1469095616c6fe3$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (4, v, $j$350e59d6558c0d64d3a6ca1a$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Lake Naivasha to Amboseli National Park$j$, $j$After breakfast, you have optional morning activities at Lake Naivasha (own expense): walking safari at Crescent Island ($25) or cycling along the lake shore. Depart Naivasha for Amboseli National Park around 10:00 AM, with lunch en route. The journey offers scenic views of Kenyan landscapes. Arrive at your camp near Amboseli in the late afternoon. If time permits and weather is clear, enjoy sunset views of Mount Kilimanjaro. Dinner and overnight at Manjaro Tented Camp or similar budget accommodation.$j$, 'en', $j$350e59d6558c0d64d3a6ca1a$j$);
    INSERT INTO tours_itinerary (_order, _parent_id, id) VALUES (5, v, $j$3d0a58452cec4cfb9544b9fa$j$); INSERT INTO tours_itinerary_locales (title, body, _locale, _parent_id) VALUES ($j$Amboseli Morning Game Drive & Return to Nairobi$j$, $j$Early wake-up for potential clear views of Mount Kilimanjaro at sunrise. After breakfast, embark on morning game drives in Amboseli National Park (7:00 AM - 10:30 AM). The park is famous for its large elephant herds, spectacular Kilimanjaro backdrop, and diverse wildlife including lions, cheetahs, giraffes, zebras, and abundant birdlife. Your guide will take you to prime viewing areas including swamp areas where elephants gather. Return to camp for check-out by 11:00 AM. Depart Amboseli for Nairobi, with lunch stop en route. Arrive in Nairobi by late afternoon (approximately 4:00-5:00 PM). Drop-off at your hotel or Jomo Kenyatta International Airport for onward travel.$j$, 'en', $j$3d0a58452cec4cfb9544b9fa$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (1, v, $j$adb85500af519277714e6db6$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Two full game drives in Masai Mara for comprehensive Big Five viewing$j$, 'en', $j$adb85500af519277714e6db6$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (2, v, $j$f45abd2af326df9d558adcf9$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Boat safari on Lake Naivasha with hippo and bird viewing$j$, 'en', $j$f45abd2af326df9d558adcf9$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (3, v, $j$c000a1c3bcb0cda68313c818$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Amboseli elephant herds with iconic Kilimanjaro backdrop$j$, 'en', $j$c000a1c3bcb0cda68313c818$j$);
    INSERT INTO tours_highlights (_order, _parent_id, id) VALUES (4, v, $j$8d2d64af163ddf0f99332212$j$); INSERT INTO tours_highlights_locales (text, _locale, _parent_id) VALUES ($j$Diverse ecosystems: savannah, freshwater lake, mountain views$j$, 'en', $j$8d2d64af163ddf0f99332212$j$);
