    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (1, v, $j$bbdf45e5d28ec3c2eb3d6d09$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Why include Lake Naivasha instead of Lake Nakuru?$j$, $j$Lake Naivasha offers unique boat safari experiences with hippo viewing that Nakuru doesn't provide. The freshwater ecosystem contrasts with Nakuru's alkaline lake, and the boat safari adds variety beyond vehicle-based game drives. Naivasha also provides better transit positioning between Mara and Amboseli, reducing travel distances.$j$, 'en', $j$bbdf45e5d28ec3c2eb3d6d09$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (2, v, $j$2e66ebf08f49c089b27027aa$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$How much time do we spend on the boat safari?$j$, $j$The included boat safari on Lake Naivasha lasts approximately 1.5 hours, typically starting around 4:00 PM. This timing offers optimal wildlife viewing as hippos become more active in the afternoon. The safari covers key hippo pods, bird colonies, and scenic lake areas with expert boat captain commentary.$j$, 'en', $j$2e66ebf08f49c089b27027aa$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (3, v, $j$d35bb4e72728326c5477bc38$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$Is 5 days enough for this three-destination safari?$j$, $j$Yes, the 5-day itinerary is carefully balanced: 2 days Masai Mara (optimal), 1 day Naivasha (boat safari focus), and 1 day Amboseli (elephant emphasis). Travel between destinations is efficient with minimal backtracking. This provides comprehensive experience without being rushed, perfect for travelers with one-week availability.$j$, 'en', $j$d35bb4e72728326c5477bc38$j$);
    INSERT INTO tours_faq (_order, _parent_id, id) VALUES (4, v, $j$4621634bfdc68c40752f2307$j$); INSERT INTO tours_faq_locales (question, answer, _locale, _parent_id) VALUES ($j$What wildlife can we see on the Lake Naivasha boat safari?$j$, $j$The boat safari primarily features: hippo pods (up to 50+ individuals), diverse water birds (fish eagles, kingfishers, cormorants, herons), occasional giraffes and antelopes drinking at shoreline, and scenic papyrus swamp ecosystems. It's a completely different wildlife experience from savannah game drives.$j$, 'en', $j$4621634bfdc68c40752f2307$j$);
